window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-94"]=[{"id":"set2-D4Dn_JTj","fingerprint":"894c6b42f6b12959","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele manopere sunt considerate etape preliminarii ale tratamentului aderent direct?","options":[{"id":"A","text":"Izolarea câmpului operator."},{"id":"B","text":"Marcarea stopurilor ocluzale."},{"id":"C","text":"Prepararea cavităţilor modificate pentru materiale aderente."},{"id":"D","text":"Realizarea sigilării dentinare."},{"id":"E","text":"Alegerea culorii."}],"correct":["A","B","E"],"pages":[68],"source":"set-2"},{"id":"set2-B2Lw0DTO","fingerprint":"c0013371747ba36e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce etape preliminarii sunt indicate specific în cazul tratamentului cariilor proximale?","options":[{"id":"A","text":"Separarea rapidă (presepararea) cu ajutorul unor pene dentare."},{"id":"B","text":"Izolarea adiţională la nivelul şanţului gingival."},{"id":"C","text":"Marcarea stopurilor ocluzale."},{"id":"D","text":"Efectuarea anesteziei."},{"id":"E","text":"Introducerea unei protecţii pentru dintele vecin."}],"correct":["A","E"],"pages":[68],"source":"set-2"},{"id":"set2-WAEfrlQh","fingerprint":"8cb0826b77f65e39","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele acțiuni fac parte din etapele propriu-zise ale tratamentului aderent direct?","options":[{"id":"A","text":"Dezinfectarea cavităţilor."},{"id":"B","text":"Alegerea culorii."},{"id":"C","text":"Prepararea cavităţilor modificate pentru materiale aderente."},{"id":"D","text":"Informarea pacientului asupra diagnosticului."},{"id":"E","text":"Restaurarea morfologică şi funcţională."}],"correct":["A","C","E"],"pages":[68],"source":"set-2"},{"id":"set2-qRUNgOCm","fingerprint":"33e3f13b43c409d7","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este succesiunea corectă a fazelor de instrumentare chirurgicală a cariilor cavitare?","options":[{"id":"A","text":"Instrumentarea inițială a marginilor cariei, excavarea dentinei necrotice, finisarea marginilor cavității preparate."},{"id":"B","text":"Excavarea dentinei necrotice, instrumentarea inițială a marginilor cariei, finisarea marginilor cavității."},{"id":"C","text":"Excavarea dentinei necrotice, finisarea marginilor cavității, stabilirea conturului marginal."},{"id":"D","text":"Instrumentarea inițială a marginilor cariei, finisarea marginilor cavității, excavarea dentinei necrotice."},{"id":"E","text":"Finisarea marginilor cavității, instrumentarea inițială a marginilor cariei, excavarea dentinei necrotice."}],"correct":["A"],"pages":[68],"source":"set-2"},{"id":"set2-QFfx3Soh","fingerprint":"c41b6af484e1c482","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce tipuri de instrumentar pot fi utilizate pentru excavarea dentinei necrotice?","options":[{"id":"A","text":"Instrumente diamantate."},{"id":"B","text":"Freze ceramice."},{"id":"C","text":"Freze extradure cu lamele dese."},{"id":"D","text":"Freze polimerice."},{"id":"E","text":"Abraziunea cu aer."}],"correct":["B","D","E"],"pages":[68],"source":"set-2"},{"id":"set2-DIyEkhCs","fingerprint":"527c46aef9e39af9","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele tipuri de instrumentar este menționat ca fiind utilizat pentru finisarea marginilor cavității preparate?","options":[{"id":"A","text":"Freze specifice pentru tehnica chemomecanică."},{"id":"B","text":"Tăietor clasic manual."},{"id":"C","text":"Laserul."},{"id":"D","text":"Sonoabraziunea."},{"id":"E","text":"Freze extradure cu lamele dese."}],"correct":["B","D","E"],"pages":[68],"source":"set-2"},{"id":"set2-6vCrYchm","fingerprint":"b98453e14b0db355","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce tehnică generală de îndepărtare a țesutului carios nu se mai utilizează în prezent?","options":[{"id":"A","text":"Îndepărtare în două etape a țesutului carios."},{"id":"B","text":"Îndepărtare selectivă a țesutului carios până în dentină necrotică."},{"id":"C","text":"Îndepărtare selectivă a țesutului carios până în dentină afectată."},{"id":"D","text":"Îndepărtare neselectivă a țesutului carios până în dentină dură."},{"id":"E","text":"Îndepărtare „stepwise” a țesutului carios."}],"correct":["D"],"pages":[68],"source":"set-2"},{"id":"set2-kFsxWbsi","fingerprint":"731763a5d0fdcb4d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care sunt principiile preparării minim invazive a cavităților pentru materiale aderente în ceea ce privește țesuturile dentare?","options":[{"id":"A","text":"Păstrarea smalțului demineralizat dacă acesta este acoperit de un material adeziv modern."},{"id":"B","text":"Îndepărtarea dentinei necrotice, cu excepția unor zone limitate în cavități profunde pentru a evita deschiderea camerei pulpare."},{"id":"C","text":"Menținerea smalțului nesusținut în toate situațiile clinice pentru a conserva structura dentară."},{"id":"D","text":"Îndepărtarea sistematică a dentinei afectate pentru a preveni recidiva carioasă."},{"id":"E","text":"Îndepărtarea tuturor țesuturilor pigmentate, indiferent de consistența lor."}],"correct":["B"],"pages":[69],"source":"set-2"},{"id":"set2-_WbL0ci5","fingerprint":"6d4d13eef16d22e6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce caracteristici descriu dentina afectată, care poate fi menținută în timpul preparării unei cavități?","options":[{"id":"A","text":"Este distrusă arhitectural și are o încărcătură bacteriană mare."},{"id":"B","text":"Prezintă o încărcătură bacteriană identică cu cea a dentinei necrotice."},{"id":"C","text":"Se află întotdeauna superficial, direct sub smalțul demineralizat."},{"id":"D","text":"Este dură, demineralizată, pigmentată și nu este distrusă arhitectural."},{"id":"E","text":"Este moale, nepigmentată și se îndepărtează ușor cu excavatorul."}],"correct":["D"],"pages":[69],"source":"set-2"},{"id":"set2-DNqHAoD7","fingerprint":"c29dda33ec2ffd6b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații referitoare la caracteristicile cavităților pentru materiale aderente sunt corecte?","options":[{"id":"A","text":"Unghiurile de cavosuprafață trebuie să fie întotdeauna mai mici de 90 de grade."},{"id":"B","text":"Marginile preparate trebuie să fie fără anfractuozități."},{"id":"C","text":"Configurația internă este rotunjită."},{"id":"D","text":"Bizotarea se efectuează de rutină în zonele supuse forțelor directe mari."},{"id":"E","text":"Crestele marginale ocluzale restante trebuie să aibă o grosime de 1,5-2 mm, unde este cazul."}],"correct":["B","C","E"],"pages":[69],"source":"set-2"},{"id":"set2--mzzIvaa","fingerprint":"823f475c4a4fed42","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În contextul preparării unei cavități de clasa I modificate pentru o carie cu orificiu mediu sau mare, care este atitudinea față de smalțul nesusținut?","options":[{"id":"A","text":"Este întotdeauna bizotat pentru a preveni fracturarea sa ulterioară."},{"id":"B","text":"Trebuie îndepărtat obligatoriu pentru a asigura retenția materialului de restaurare."},{"id":"C","text":"Păstrarea sa este condiționată de utilizarea frezelor de fisurotomie la turație înaltă."},{"id":"D","text":"Se păstrează doar la premolari, dar se îndepărtează întotdeauna la molari."},{"id":"E","text":"Se poate păstra și căptuși cu materiale aderente, dar cu precauție în zonele cu forțe ocluzale mari."}],"correct":["E"],"pages":[69],"source":"set-2"},{"id":"set2-jcAbXx4n","fingerprint":"32831cb33f155e64","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile finale ale unei cavități de clasa I modificate pentru materiale aderente, rezultată din tratamentul unei carii cu orificiu mediu/mare?","options":[{"id":"A","text":"Unghiurile externe sunt ascuțite pentru o delimitare precisă a preparației."},{"id":"B","text":"Marginile se bizotează în mod curent în zonele supuse direct forțelor mecanice."},{"id":"C","text":"Lățimea crestelor marginale este de minim 1,5 mm la molari și 2 mm la premolari."},{"id":"D","text":"Lățimea crestelor marginale este de minim 1,5 mm la premolari și 2 mm la molari."},{"id":"E","text":"Se realizează înglobarea în conturul marginal a șanțurilor învecinate cu colorații sau aspect suspicios."}],"correct":["D","E"],"pages":[69],"source":"set-2"},{"id":"set2-0Yo2HAdl","fingerprint":"d00c2a27ff72837e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce descrie corect o carie cavitară cu orificiu mic de deschidere, localizată în șanțuri și fosete?","options":[{"id":"A","text":"Gradul de deschidere la nivelul smalțului este direct proporțional cu evoluția în profunzime."},{"id":"B","text":"Necesită îndepărtarea obligatorie a smalțului nesusținut pentru acces."},{"id":"C","text":"Prezintă întotdeauna o cantitate mare de dentină necrotică."},{"id":"D","text":"Preparația rezultată necesită bizotare sistematică în zonele ocluzale."},{"id":"E","text":"Conduce la cavități mici, cu profunzime variabilă și întindere mică în suprafață."}],"correct":["E"],"pages":[69],"source":"set-2"},{"id":"set2-HajPbcYn","fingerprint":"c48f969e3657b368","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele reprezintă o formă clinică de carie cavitară care conduce la realizarea unei cavități de clasa a II-a modificate pentru materiale aderente?","options":[{"id":"A","text":"Leziune carioasă necavitară (pată albă) pe suprafața proximală."},{"id":"B","text":"Carie cu orificiu mic de deschidere, localizată în foseta mezială a unui molar."},{"id":"C","text":"Carie cavitară cu subminare a crestei marginale și evoluție subgingivală."},{"id":"D","text":"Carie localizată pe versantul cuspidian vestibular al unui premolar."},{"id":"E","text":"Carie localizată exclusiv în șanțul central ocluzal, fără extindere proximală."}],"correct":["C"],"pages":[69],"source":"set-2"},{"id":"set2-OJgvlta-","fingerprint":"c59b4491851a8be1","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care sunt caracteristicile unei cavități de tip „casetă modificată” pentru materiale aderente, preparată în condiții de acces direct?","options":[{"id":"A","text":"Configurația internă este una paralelipipedică, cu unghiuri bine definite."},{"id":"B","text":"Se prepară atunci când nu există acces direct la leziunea carioasă proximală."},{"id":"C","text":"Pereții cavității includ peretele ocluzal, gingival, vestibular, oral și parapulpar."},{"id":"D","text":"Marginile de smalț nu se bizotează niciodată, din cauza forțelor mecanice directe."},{"id":"E","text":"Prezintă întotdeauna o profunzime mare, extinzându-se mult în dentină."}],"correct":["C"],"pages":[70],"source":"set-2"},{"id":"set2-UXUezy9n","fingerprint":"ef333393e3a6ae05","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect o cavitate de tip „tunel”?","options":[{"id":"A","text":"Este indicată cu predilecție la premolari, datorită riscului redus de complicații."},{"id":"B","text":"Prezintă un aspect intern rotunjit, cu o traiectorie ocluzo-proximală ușor curbă."},{"id":"C","text":"Există riscul deschiderii camerei pulpare în timpul preparării sale."},{"id":"D","text":"Zona de smalț marginal de la nivel proximal este preparată ușor convergentă."},{"id":"E","text":"Datorită configurației sale conservatoare, are de obicei o profunzime superficială."}],"correct":["B","C"],"pages":[70],"source":"set-2"},{"id":"set2-Ucb0exUj","fingerprint":"de5347566adae576","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce diferențiază o cavitate de tip „galerie” deschisă de una închisă?","options":[{"id":"A","text":"Configurația internă, care este rotunjită la cea deschisă și paralelipipedică la cea închisă."},{"id":"B","text":"Prezența sau absența peretelui vestibular."},{"id":"C","text":"Prezența sau absența peretelui parapulpar."},{"id":"D","text":"Posibilitatea de a bizota muchia de intersecție cu suprafața vestibulară."},{"id":"E","text":"Indicația specifică; cea deschisă se prepară la molari, iar cea închisă la premolari."}],"correct":["B"],"pages":[70],"source":"set-2"},{"id":"set2-kjf7UvfK","fingerprint":"6edbfc72945c5568","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce tip de cavitate se prepară în cazul unei carii cu o întrerupere medie a crestei marginale?","options":[{"id":"A","text":"Cavitate de tip „casetă modificată”."},{"id":"B","text":"Cavitate de tip „slot”."},{"id":"C","text":"Cavitate clasică de clasa a II-a modificată pentru materiale aderente."},{"id":"D","text":"Cavitate de tip „tunel”."},{"id":"E","text":"Cavitate de tip „picătură”."}],"correct":["B"],"pages":[70],"source":"set-2"},{"id":"set2-yHD4yoz1","fingerprint":"92be8feacd14af64","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Referitor la peretele gingival al cavităților proximale modificate, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Marginea de smalț gingival subminată trebuie întotdeauna îndepărtată pentru a preveni fracturile marginale."},{"id":"B","text":"Poate deveni concav ca urmare a îndepărtării dentinei infectate."},{"id":"C","text":"Atunci când este plan și smalțul este susținut, realizează un unghi de aproximativ 90 de grade cu restul suprafeței proximale."},{"id":"D","text":"Pragul gingival se bizotează în mod obișnuit pentru a asigura o mai bună retenție a materialului."},{"id":"E","text":"Poziția sa este întotdeauna supragingivală pentru a facilita igienizarea și a preveni inflamația gingivală."}],"correct":["B","C"],"pages":[70],"source":"set-2"},{"id":"set2-A3C03F36","fingerprint":"2552cd5e28a3c153","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Cum sunt caracterizați pereții vestibular și oral ai unei cavități proximale modificate?","options":[{"id":"A","text":"Realizează unghiuri ascuțite, sub 90 de grade, cu suprafața externă proximală."},{"id":"B","text":"Au o deschidere fixă în plan transversal, standardizată pentru fiecare tip de dinte."},{"id":"C","text":"Au poziții variabile în plan vertical, putând fi ușor convergenți sau paraleli."},{"id":"D","text":"Trebuie să depășească obligatoriu aria de contact în plan transversal."},{"id":"E","text":"Sunt întotdeauna strict paraleli în plan vertical pentru a asigura retenția."}],"correct":["C"],"pages":[70],"source":"set-2"},{"id":"set2-17y0mBkL","fingerprint":"7a1ed46914a95845","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În ce condiții pot fi unite o carie proximală și una ocluzală într-o singură cavitate proximo-ocluzală?","options":[{"id":"A","text":"Indiferent de grosimea punții de smalț, dacă ambele leziuni sunt în stadiu de cavitate."},{"id":"B","text":"Numai dacă se îndepărtează o obturație veche de amalgam care le acoperă pe amândouă."},{"id":"C","text":"În cazul în care puntea de smalț dintre cavități este demineralizată, având o grosime de peste 2 mm."},{"id":"D","text":"Dacă puntea de smalț sănătos și susținut dentinar dintre ele este mai subțire de 1 mm."},{"id":"E","text":"Când caria proximală coexistă cu leziuni carioase ocluzale multiple, indiferent de distanța dintre ele."}],"correct":["D"],"pages":[70],"source":"set-2"},{"id":"set2-0dB-DtJM","fingerprint":"c3392877c3935c14","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele tipuri de cavități pot avea și o deschidere ocluzală?","options":[{"id":"A","text":"Cavitate de tip „picătură”."},{"id":"B","text":"Cavitate de tip „galerie”."},{"id":"C","text":"Cavitate de tip „slot-cutie”."},{"id":"D","text":"Cavitate de clasa a II-a modificată pentru materiale aderente."},{"id":"E","text":"Cavitate de tip „casetă”."}],"correct":["A","C","D"],"pages":[70],"source":"set-2"},{"id":"set2-X2jNj9li","fingerprint":"62b00b236258ba2c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care sunt criteriile principale de clasificare pentru sistemele suplimentare de retenție, precum pinurile și știfturile dentinare?","options":[{"id":"A","text":"După materialul de confecționare și modalitatea de fixare."},{"id":"B","text":"După tipul cavității (clasa a III-a sau a IV-a) și localizarea dintelui."},{"id":"C","text":"După turația frezei utilizate pentru preparare și tipul de adeziv folosit."},{"id":"D","text":"După adâncimea de inserție și diametrul acestora."},{"id":"E","text":"După producătorul sistemului și compoziția aliajului metalic."}],"correct":["A"],"pages":[71],"source":"set-2"},{"id":"set2-I-x6gPeJ","fingerprint":"e6f123a94a3707ec","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele reguli se aplică la prepararea locașurilor pentru pinurile parapulpare?","options":[{"id":"A","text":"Se plasează la o distanță sigură de minim 1 mm în interiorul joncțiunii amelo-dentinare."},{"id":"B","text":"Excavarea se realizează cu freze speciale, la turație înaltă, pentru a asigura precizia."},{"id":"C","text":"Fixarea prin cimentare cu material rășinic dual nu necesită utilizarea unui sistem adeziv."},{"id":"D","text":"Locașurile se prepară în dentina peretelui gingival."},{"id":"E","text":"Dacă se aplică mai multe pinuri, distanța dintre ele trebuie să fie de cel puțin 2 mm."}],"correct":["A","D","E"],"pages":[71],"source":"set-2"},{"id":"set2-9NNSMDNS","fingerprint":"490b863bf2f45b1b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este criteriul definitoriu care diferențiază o cavitate de clasa a IV-a de una de clasa a III-a la dinții frontali?","options":[{"id":"A","text":"Localizarea subgingivală a leziunii carioase."},{"id":"B","text":"Subminarea crestei marginale orale."},{"id":"C","text":"Prezența accesului direct proximal."},{"id":"D","text":"Necesitatea utilizării sistemelor suplimentare de retenție."},{"id":"E","text":"Implicarea muchiei incizale."}],"correct":["E"],"pages":[71],"source":"set-2"},{"id":"set2-X5N4Pgxr","fingerprint":"3d9da25f4e556154","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Conform căror principii se realizează prepararea cavităților proximale pe dinții frontali?","options":[{"id":"A","text":"Muchiile de smalț vestibulare nu se bizotează pentru a menține un contact optim cu materialul de restaurare."},{"id":"B","text":"Se recomandă utilizarea instrumentelor rotative exclusiv la turație înaltă pentru eficiență."},{"id":"C","text":"Accesul se realizează întotdeauna dinspre vestibular pentru o vizibilitate maximă asupra leziunii."},{"id":"D","text":"Aspectul fizionomic este prioritar, motiv pentru care accesul se face, de regulă, dinspre oral."},{"id":"E","text":"Smalțul vestibular nesusținut trebuie întotdeauna îndepărtat pentru a crește rezistența restaurării."}],"correct":["D"],"pages":[71],"source":"set-2"},{"id":"set2-d9HW_6Fz","fingerprint":"0402c8dc302f6553","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În ce situații este acceptabil un acces diferit de cel oral pentru prepararea unei cavități proximale la un dinte frontal?","options":[{"id":"A","text":"Când leziunea carioasă este clasificată ca fiind de clasa a IV-a."},{"id":"B","text":"Când există modificări de poziție, înclinație sau rotație care obstrucționează calea orală."},{"id":"C","text":"Când creasta marginală vestibulară este distrusă."},{"id":"D","text":"Când este necesară aplicarea unui pin parapulpar."},{"id":"E","text":"Când există un acces direct proximal."}],"correct":["B","C","E"],"pages":[71],"source":"set-2"},{"id":"set2-600l0_q5","fingerprint":"56be2e43bbe3d0d6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce descrie corect managementul țesuturilor dentare în timpul preparării cavităților proximale la dinții frontali?","options":[{"id":"A","text":"Dentina necrotică poate fi lăsată pe loc dacă este acoperită de un material de coafaj."},{"id":"B","text":"Smalțul vestibular nesusținut este conservat."},{"id":"C","text":"Smalțul demineralizat este singurul țesut care trebuie îndepărtat."},{"id":"D","text":"Muchiile de smalț vestibulare sunt lăsate ascuțite pentru a maximiza retenția."},{"id":"E","text":"Smalțul oral nesusținut este, de asemenea, conservat pentru a menține structura dintelui."}],"correct":["B"],"pages":[71],"source":"set-2"},{"id":"set2-UpbcuhPw","fingerprint":"83ef1a7529c412ba","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici are o cavitate de clasa a III-a modificată, preparată cu acces oral, atunci când nu există acces direct?","options":[{"id":"A","text":"Este o cavitate mică, realizată minim invaziv."},{"id":"B","text":"Peretele oral este întotdeauna conservat în totalitate."},{"id":"C","text":"Este, de regulă, o cavitate profundă, extinsă spre pulpă."},{"id":"D","text":"Pereții laterali sunt convergenți spre suprafață pentru a asigura retenția."},{"id":"E","text":"Are o suprafață internă rotunjită."}],"correct":["A","E"],"pages":[71],"source":"set-2"},{"id":"set2-S6-7E_h1","fingerprint":"1236830e1ca80158","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În ce situație se prepară o casetă modificată pentru materiale aderente în tratamentul unei carii de clasa a III-a?","options":[{"id":"A","text":"Când leziunea carioasă a subminat creasta marginală vestibulară."},{"id":"B","text":"Întotdeauna, deoarece este cea mai conservatoare abordare."},{"id":"C","text":"Doar în cazul leziunilor carioase superficiale."},{"id":"D","text":"Când există acces direct, de exemplu dacă dintele vecin este absent sau prezintă o distrucție mare."},{"id":"E","text":"Atunci când accesul se realizează obligatoriu dinspre zona orală."}],"correct":["D"],"pages":[71],"source":"set-2"},{"id":"set2-ygwoIhNO","fingerprint":"9481b252255d0545","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile preparațiilor cu extindere medie sau mare în cazul cariilor cu subminarea crestelor vestibulare și orale?","options":[{"id":"A","text":"Peretele gingival cu smalț trebuie să realizeze unghiuri drepte cu restul suprafeței proximale."},{"id":"B","text":"Peretele gingival cu smalț este frecvent bizotat pentru a îmbunătăți închiderea marginală."},{"id":"C","text":"Pentru suplimentarea retenției în cavitățile mari, se poate bizota smalțul oral."},{"id":"D","text":"Pereții laterali sunt întotdeauna divergenți spre suprafață pentru a asigura retenția."},{"id":"E","text":"Configurația internă este întotdeauna rotunjită."}],"correct":["A","C","E"],"pages":[72],"source":"set-2"},{"id":"set2-Afv6o7Zl","fingerprint":"0811e99b3d876475","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații referitoare la tehnica bizotării sunt adevărate?","options":[{"id":"A","text":"Poziția stopurilor ocluzale de gradul al II-lea nu influențează decizia de a bizota."},{"id":"B","text":"Bizotarea se realizează numai în smalț."},{"id":"C","text":"Bizotarea vestibulară se realizează pentru a crește retenția obturației."},{"id":"D","text":"Bizotarea orală se efectuează în principal din considerente estetice."},{"id":"E","text":"Se utilizează frecvent freze de finisare extradure sau instrumentar abraziv la turație înaltă."}],"correct":["B","E"],"pages":[72],"source":"set-2"},{"id":"set2-TLl_ur2C","fingerprint":"e0050ddc9e1b8352","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele sunt considerate forme de retenție suplimentară în preparațiile de clasa a IV-a?","options":[{"id":"A","text":"Configurația internă rotunjită."},{"id":"B","text":"Șanțurile dentinare."},{"id":"C","text":"Bizoul."},{"id":"D","text":"Fațetarea directă a suprafeței vestibulare."},{"id":"E","text":"Sisteme suplimentare de retenție, precum pinurile parapulpare."}],"correct":["B","C","E"],"pages":[72],"source":"set-2"},{"id":"set2-yIePFS9S","fingerprint":"2aa632e9427ca892","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce dimensiuni sunt specificate pentru bizoul realizat în cadrul preparațiilor de clasa a IV-a?","options":[{"id":"A","text":"Lungimea bizoului este întotdeauna sub 1 mm."},{"id":"B","text":"Pentru pierderi vestibulare mari, bizoul vestibular are o lățime de minim 2 mm."},{"id":"C","text":"Lățimea bizoului vestibular este de maxim 1 mm."},{"id":"D","text":"Lățimea bizoului oral este mai îngustă, de maxim 1 mm."},{"id":"E","text":"Lățimea bizoului vestibular și a celui oral sunt întotdeauna egale."}],"correct":["B","D"],"pages":[72],"source":"set-2"},{"id":"set2-tEcg9jGg","fingerprint":"7bc2922cd38ed7f5","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În ce condiții se pot realiza șanțurile dentinare în cavitățile de clasa a IV-a?","options":[{"id":"A","text":"Se prepară cât mai conservativ posibil."},{"id":"B","text":"Se realizează la turație înaltă, cu freze diamantate."},{"id":"C","text":"Pot fi realizate la intersecția dintre pereții laterali și cel parapulpar, dacă adâncimea cavității permite."},{"id":"D","text":"Se pot prepara la nivelul muchiei incizale restante."},{"id":"E","text":"Sunt recomandate de rutină pentru a spori retenția."}],"correct":["A","C","D"],"pages":[72],"source":"set-2"},{"id":"set2-OTPZ_ev5","fingerprint":"53bbd8ac7a8d1666","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile preparațiilor mici de clasa a V-a, fără extindere subgingivală?","options":[{"id":"A","text":"Peretele axial este întotdeauna neted și regulat."},{"id":"B","text":"Se realizează frecvent cu instrumentar rotativ sferic la turație înaltă."},{"id":"C","text":"Prezintă o configurație internă rotunjită."},{"id":"D","text":"Bizotarea este recomandată pe marginea gingivală pentru retenție."},{"id":"E","text":"Pereții laterali sunt ușor divergenți către exterior."}],"correct":["C","E"],"pages":[72],"source":"set-2"},{"id":"set2-2yYZvnQ3","fingerprint":"27f347513a87b33f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce principiu important se aplică în prepararea cavităților de clasa a V-a în ceea ce privește managementul smalțului?","options":[{"id":"A","text":"Păstrarea smalțului cervical nesusținut compromite închiderea marginală."},{"id":"B","text":"Toate marginile de smalț ale cavității trebuie să fie bizotate pentru o adeziune optimă."},{"id":"C","text":"Smalțul nesusținut de la nivel cervical trebuie întotdeauna îndepărtat."},{"id":"D","text":"Bizotarea marginii gingivale este esențială deoarece zona este supusă forțelor mecanice directe."},{"id":"E","text":"Se poate practica bizotarea pe marginea incizală/ocluzală a preparației pentru retenție și fizionomie."}],"correct":["E"],"pages":[72],"source":"set-2"},{"id":"set2-EHEX9p6q","fingerprint":"cf5578f6f78a5303","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații referitoare la bizotarea marginilor cavităților de clasa a V-a sunt corecte?","options":[{"id":"A","text":"Se efectuează și pe marginile de cement pentru a îmbunătăți sigilarea."},{"id":"B","text":"Este obligatorie în cazul obturațiilor cu cimenturi cu ionomeri de sticlă."},{"id":"C","text":"Se realizează exclusiv în smalț."},{"id":"D","text":"Are un scop atât fizionomic, cât și retentiv."},{"id":"E","text":"Lățimea zonei de smalț bizotate poate varia între 0,5 mm și 1,5 mm."}],"correct":["C","D","E"],"pages":[73],"source":"set-2"},{"id":"set2-SxBy1oUF","fingerprint":"1a05b4601f97a59d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici sunt specifice preparațiilor extinse în cazul cavităților de clasa a V-a modificate pentru materiale aderente?","options":[{"id":"A","text":"Se pot realiza șanțuri la intersecția peretelui axial cu pereții laterali pentru creșterea retenției în cavități foarte mari."},{"id":"B","text":"Pereții laterali formează întotdeauna unghiuri obtuze cu suprafața dintelui pentru a conserva structura dentară."},{"id":"C","text":"Prezintă o configurație internă cu unghiuri ascuțite pentru a maximiza retenția mecanică."},{"id":"D","text":"Marginile de cement, dacă sunt prezente, realizează unghiuri de 90° cu suprafața dintelui."},{"id":"E","text":"Peretele axial are un contur nivelat și ușor convex."}],"correct":["A","D","E"],"pages":[73],"source":"set-2"},{"id":"set2-U00z_RLk","fingerprint":"8f4b2a2ba9594c57","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Conform teoriilor moderne, în ce situație aplicarea straturilor clasice de protecție pulpo-dentinară nu mai este considerată necesară la utilizarea materialelor aderente?","options":[{"id":"A","text":"Când lățimea bizoului de smalț depășește 1,5 mm."},{"id":"B","text":"Când se utilizează exclusiv amalgamul ca material de restaurare."},{"id":"C","text":"Doar în cazul dinților frontali, din considerente fizionomice."},{"id":"D","text":"Când grosimea stratului de dentină restantă este de aproximativ 2 mm."},{"id":"E","text":"În toate cavitățile cu profunzime mare, indiferent de materialul de restaurare."}],"correct":["D"],"pages":[73],"source":"set-2"},{"id":"set2-XVG4ELtR","fingerprint":"7913d097b9a3bd1b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt argumentele care susțin viziunea modernă privind eliminarea straturilor clasice de protecție pulpo-dentinară în cazul utilizării materialelor aderente?","options":[{"id":"A","text":"Sistemele de adeziune moderne sigilează eficient plaga dentinară."},{"id":"B","text":"Straturile clasice sunt incompatibile chimic cu sistemele adezive moderne."},{"id":"C","text":"Aplicarea straturilor clasice reduce suprafața de adeziune a materialului de restaurare."},{"id":"D","text":"Materialele aderente oferă o izolare termică eficientă."},{"id":"E","text":"Materialele aderente stimulează activ neodentinogeneza, înlocuind funcția linerilor."}],"correct":["A","C","D"],"pages":[73],"source":"set-2"},{"id":"set2-ieNBjMTI","fingerprint":"80e1e9a6565d52ef","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații despre straturile de protecție pulpo-dentinară sunt corecte?","options":[{"id":"A","text":"În abordarea clasică, straturile de protecție se aplică până în apropierea joncțiunii amelo-dentinare."},{"id":"B","text":"Un strat de protecție cu o grosime mai mare de 1 mm este denumit bază."},{"id":"C","text":"Protecția pulpară pasivă include acțiuni antiinflamatorii și dezinfectante."},{"id":"D","text":"Un strat de protecție cu o grosime de 0,5 mm este denumit liner."},{"id":"E","text":"În abordarea modernă, straturile protectoare se aplică obligatoriu în toate cavitățile, indiferent de profunzime."}],"correct":["A","B","D"],"pages":[73],"source":"set-2"},{"id":"set2-LFmjsTce","fingerprint":"66f136990542c868","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce particularitate prezintă preparațiile destinate obturării cu cimenturi cu ionomeri de sticlă modificate cu rășini?","options":[{"id":"A","text":"Pereții laterali trebuie să fie întotdeauna divergenți spre suprafața ocluzală."},{"id":"B","text":"Necesită întotdeauna realizarea de șanțuri de retenție suplimentară."},{"id":"C","text":"Este obligatorie aplicarea unui strat de bază cu grosime de peste 1 mm."},{"id":"D","text":"Marginile preparației nu sunt bizotate, indiferent de grosimea smalțului."},{"id":"E","text":"Configurația internă trebuie să fie cu unghiuri ascuțite."}],"correct":["D"],"pages":[73],"source":"set-2"},{"id":"set2-B8hUvNdU","fingerprint":"c74fdab6d54005fe","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte cu privire la caracteristicile generale ale linerilor?","options":[{"id":"A","text":"Se aplică în straturi groase, de peste 1 mm."},{"id":"B","text":"Materialele cu efect activ suplimentar sunt bazate pe ciment fosfat de zinc."},{"id":"C","text":"Asigură în principal o protecție pasivă de natură mecanică."},{"id":"D","text":"Grosimea stratului aplicat este de regulă între 0,2 și 1 mm."},{"id":"E","text":"Anumite tipuri pot avea efect activ neodentinogenetic."}],"correct":["D","E"],"pages":[74],"source":"set-2"},{"id":"set2-23thyP8M","fingerprint":"6801c996f7c17c24","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este o diferență fundamentală între lineri și baze?","options":[{"id":"A","text":"Bazele au o rezistență mecanică inferioară linerilor."},{"id":"B","text":"Cimenturile cu ionomeri de sticlă sunt utilizate exclusiv ca lineri."},{"id":"C","text":"Bazele se aplică în strat mai subțire (0,2-1 mm), iar linerii în strat mai gros (peste 1 mm)."},{"id":"D","text":"Linerii oferă o protecție pasivă predominant chimică, în timp ce bazele oferă o protecție pasivă predominant mecanică."},{"id":"E","text":"Doar linerii pot avea efecte active, precum cel neodentinogenetic."}],"correct":["D"],"pages":[74],"source":"set-2"},{"id":"set2--drHzCYZ","fingerprint":"b578205ef3a66687","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici definesc materialele biologic active autopolimerizabile cu rezistență mecanică scăzută?","options":[{"id":"A","text":"Se aplică în straturi mai groase de 1 mm."},{"id":"B","text":"Au un timp de priză crescut."},{"id":"C","text":"Au efecte biologice crescute și un cost rezonabil."},{"id":"D","text":"Prezintă o capacitate redusă de sigilare a plăgii dentinare."},{"id":"E","text":"Sunt formulate pe bază de silicați de calciu."}],"correct":["C","D"],"pages":[74],"source":"set-2"},{"id":"set2-M8x4rtiA","fingerprint":"76d2f1b1a1a49ede","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Prin ce se deosebesc materialele biologic active fotopolimerizabile de omoloagele lor autopolimerizabile?","options":[{"id":"A","text":"Capacitatea de sigilare a plăgii dentinare este inferioară, din cauza componentei rășinice."},{"id":"B","text":"Au o rezistență mecanică mai scăzută."},{"id":"C","text":"Se dizolvă mai ușor în mediul bucal."},{"id":"D","text":"Sunt variante modificate cu rășini ale materialelor pe bază de hidroxid de calciu și silicați de calciu."},{"id":"E","text":"Prezintă efecte biologice reduse."}],"correct":["D","E"],"pages":[74],"source":"set-2"},{"id":"set2-KIoa8Mad","fingerprint":"5f0eb3941dc2f6f3","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt aspectele corecte referitoare la condiționarea structurilor dure dentare înaintea aplicării cimenturilor cu ionomeri de sticlă (CIS)?","options":[{"id":"A","text":"Scopul principal la nivel dentinar este dizolvarea dopurilor intratubulare pentru a crește adeziunea."},{"id":"B","text":"Adeziunea la structura dură dentară se realizează prin schimb ionic."},{"id":"C","text":"Adeziunea cimenturilor cu ionomeri de sticlă este mai puternică la dentină decât la smalț."},{"id":"D","text":"Condiționarea se aplică doar pe smalț, nu și pe dentină."},{"id":"E","text":"Se utilizează acid poliacrilic, un acid organic slab, frecvent în concentrație de 10%."}],"correct":["B","E"],"pages":[74],"source":"set-2"},{"id":"set2-bb9mY2EM","fingerprint":"d07017108d3e7b05","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele materiale pot fi utilizate ca baze?","options":[{"id":"A","text":"Cimenturile cu ionomeri de sticlă (CIS)."},{"id":"B","text":"Biomaterialele cu silicat de calciu."},{"id":"C","text":"Cimentul fosfat de zinc (FOZ)."},{"id":"D","text":"Suspensiile pe bază de hidroxid de calciu."},{"id":"E","text":"Lacurile-varnish."}],"correct":["A","B","C"],"pages":[74],"source":"set-2"},{"id":"set2-WYbUpPST","fingerprint":"e6cb706f5632c4a7","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici sunt specifice materialelor biologic active autopolimerizabile cu rezistență mecanică crescută?","options":[{"id":"A","text":"Au un cost crescut și un timp de priză prelungit."},{"id":"B","text":"Se dizolvă ușor în mediul oral."},{"id":"C","text":"Au la bază hidroxidul de calciu."},{"id":"D","text":"Efectele biologice sunt inferioare variantelor cu rezistență scăzută."},{"id":"E","text":"Prezintă o capacitate de sigilare superioară materialelor pe bază de hidroxid de calciu."}],"correct":["A","E"],"pages":[74],"source":"set-2"},{"id":"set2-kXre33uX","fingerprint":"881aeefba441690a","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este o indicație principală pentru aplicarea linerilor din materiale cu rășini?","options":[{"id":"A","text":"Doar în cavități superficiale, datorită rezistenței mecanice scăzute."},{"id":"B","text":"Pentru că generează un strat ne-rigid după evaporarea solventului."},{"id":"C","text":"Exclusiv pentru efectul lor biologic crescut."},{"id":"D","text":"Pentru compensarea contracției de polimerizare a compozitelor."},{"id":"E","text":"Pentru a reduce contracția de polimerizare a amalgamului."}],"correct":["D"],"pages":[74],"source":"set-2"},{"id":"set2-NqYhEqVJ","fingerprint":"4242162834428066","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte referitoare la condiționarea structurilor dure dentare cu acid poliacrilic înaintea aplicării cimenturilor cu ionomeri de sticlă (CIS) sau a cimenturilor cu ionomeri de sticlă modificate cu rășini (CIMR)?","options":[{"id":"A","text":"Adeziunea rezultată este mai puternică la dentină decât la smalț."},{"id":"B","text":"Timpul mediu de menținere a acidului pe dentină este de 20 de secunde."},{"id":"C","text":"Scopul său principal este de a facilita contactul optim între material și structura dură dentinară."},{"id":"D","text":"Reprezintă un acid organic, slab, utilizat frecvent în concentrație de 10%."},{"id":"E","text":"Rolul principal la nivel dentinar este dizolvarea dopurilor intratubulare de detritus."}],"correct":["B","C","D"],"pages":[75],"source":"set-2"},{"id":"set2-f-ReIlUb","fingerprint":"be11d3d3a2f9da12","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Cum este definit un sistem adeziv de generația a V-a, conform clasificării hibride?","options":[{"id":"A","text":"Acidul și primerul sunt amestecate, iar adezivul este separat."},{"id":"B","text":"Conține nanoumplutură ca element distinctiv."},{"id":"C","text":"Conține cele trei componente (acid, primer, adeziv) în recipiente separate."},{"id":"D","text":"Acidul demineralizant este separat, în timp ce primerul și adezivul sunt amestecate."},{"id":"E","text":"Toate cele trei componente se află în același recipient."}],"correct":["D"],"pages":[75],"source":"set-2"},{"id":"set2-k_ol91Od","fingerprint":"b38dc60f8200c86b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt rolurile acidului ortofosforic la nivelul dentinei atunci când este utilizat ca parte a unui sistem adeziv?","options":[{"id":"A","text":"Crearea de microretenții mecanice în dentina intertubulară și peritubulară."},{"id":"B","text":"Îndepărtarea detritusului dentinar remanent (smear layer) și a dopurilor de detritus (smear plugs)."},{"id":"C","text":"Curățarea suprafeței dentinare fără a îndepărta dopurile de detritus intratubulare."},{"id":"D","text":"Dezvelirea fibrelor de colagen prin îndepărtarea structurii mineralizate înconjurătoare."},{"id":"E","text":"Transformarea țesutului dentinar dintr-unul hidrofil într-unul hidrofob."}],"correct":["A","B","D"],"pages":[75],"source":"set-2"},{"id":"set2--dkpGPmR","fingerprint":"9de81b8a2e3a6908","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este rolul unui solvent precum acetona sau etanolul din compoziția primerului, atunci când acesta este aplicat pe o dentină umedă?","options":[{"id":"A","text":"Transportul moleculelor monomerice bifuncționale și evaporarea lentă."},{"id":"B","text":"Demineralizarea dentinei peritubulare pentru a crea microretenții."},{"id":"C","text":"Facilitarea schimbului ionic între materialul adeziv și dentină."},{"id":"D","text":"Îndepărtarea apei în exces din dentina umedă și evaporarea rapidă."},{"id":"E","text":"Rehidratarea rețelei de colagen deshidratată și colabată."}],"correct":["D"],"pages":[75],"source":"set-2"},{"id":"set2-rZ6vZPhc","fingerprint":"3f25536010814ce6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații compară corect utilizarea acidului ortofosforic și a acidului poliacrilic în prepararea structurilor dentare dure?","options":[{"id":"A","text":"Acidul ortofosforic este utilizat înaintea aplicării rășinilor compozite, în timp ce acidul poliacrilic este utilizat pentru cimenturile cu ionomeri de sticlă."},{"id":"B","text":"Ambii acizi au rolul de a îndepărta dopurile de detritus dentinar (smear plugs)."},{"id":"C","text":"La nivel dentinar, acidul ortofosforic transformă țesutul hidrofil în hidrofob, iar acidul poliacrilic doar curăță suprafața."},{"id":"D","text":"Timpul maxim de aplicare pe dentină pentru acidul ortofosforic este 10-15 secunde, iar timpul mediu pentru acidul poliacrilic este de 20 de secunde."},{"id":"E","text":"Acidul poliacrilic creează microretenții mecanice prin demineralizarea smalțului, în timp ce acidul ortofosforic are doar un rol secundar de curățare la acest nivel."}],"correct":["A","D"],"pages":[75],"source":"set-2"},{"id":"set2-ozHRm6Kl","fingerprint":"c062493bf090e4bb","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Cum se desfășoară corect etapa de gravaj acid total cu acid ortofosforic?","options":[{"id":"A","text":"Se aplică doar pe smalț timp de 15-30 de secunde, evitând contactul cu dentina."},{"id":"B","text":"Se aplică pe ambele structuri și se lasă să acționeze până la uscarea completă, fără spălare."},{"id":"C","text":"Se aplică întâi pe smalț pentru aproximativ 15 secunde, apoi se aplică și pe dentină, lăsând să acționeze împreună încă 15 secunde."},{"id":"D","text":"Se aplică simultan pe smalț și dentină pentru un timp total de 15 secunde."},{"id":"E","text":"Se aplică întâi pe dentină pentru 15 secunde, apoi se extinde pe smalț pentru încă 15 secunde."}],"correct":["C"],"pages":[75],"source":"set-2"},{"id":"set2-U5gbXJLV","fingerprint":"3de4caa1cb0e503b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte referitoare la rolurile și caracteristicile unui strat de adeziv dentar?","options":[{"id":"A","text":"La nivelul smalțului, rolul principal al adezivului este de a remineraliza microretențiile create de primer."},{"id":"B","text":"Un strat de adeziv superficial mai gros este benefic pentru absorbția tensiunilor induse de contracția de polimerizare."},{"id":"C","text":"Grosimea stratului superficial de adeziv trebuie să fie minimă pentru a reduce tensiunile."},{"id":"D","text":"La nivelul dentinei, adezivul pătrunde în tubulii deschiși și în spațiile demineralizate."},{"id":"E","text":"Verificarea clinică a aplicării corecte a adezivului se face prin observarea unui aspect mat, neuniform."}],"correct":["B","D"],"pages":[76],"source":"set-2"},{"id":"set2-TpC7pVqb","fingerprint":"819c1f633bfab799","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce definește stratul hibrid în contextul procedurilor adezive dentare?","options":[{"id":"A","text":"Zona de joncțiune dintre un ciment cu ionomer de sticlă și sistemul adeziv."},{"id":"B","text":"Țesutul dentinar demineralizat exclusiv de acidul ortofosforic, înainte de aplicarea primerului."},{"id":"C","text":"Stratul rezultat prin întrepătrunderea țesutului dentinar cu primerul și adezivul."},{"id":"D","text":"Stratul superficial de adeziv nepolimerizat care facilitează adeziunea compozitului."},{"id":"E","text":"Combinația de monomeri care formează adezivul înainte de aplicarea acestuia pe dinte."}],"correct":["C"],"pages":[76],"source":"set-2"},{"id":"set2-d6xy2dUk","fingerprint":"0afcd1cafead76f9","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile sistemelor adezive de generațiile IV și V, de tip „etch and rinse”?","options":[{"id":"A","text":"Aplicarea acidului demineralizant este urmată de spălarea acestuia într-un timp separat."},{"id":"B","text":"Oferă o închidere marginală optimă la nivelul structurilor dentare."},{"id":"C","text":"Nu necesită un timp separat de demineralizare la nivelul smalțului pentru restaurările polimerice."},{"id":"D","text":"Primerul utilizat este frecvent pe bază de apă, necesitând o dentină uscată cu jet de aer."},{"id":"E","text":"Se recomandă aplicarea lor pe o dentină umedă, obținută prin uscare cu o buletă de vată."}],"correct":["A","B","E"],"pages":[76],"source":"set-2"},{"id":"set2-H4TerrbZ","fingerprint":"f9f140fc8cfa835e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este o particularitate a sistemelor adezive de generațiile VI și VII?","options":[{"id":"A","text":"Pot fi utilizate cu succes pentru aplicarea straturilor interne de înlocuire a dentinei."},{"id":"B","text":"Se aplică de preferat pe o dentină umedă, deoarece primerul este frecvent pe bază de alcool."},{"id":"C","text":"Acidul demineralizant este aplicat și apoi spălat într-un timp separat, similar sistemelor de generația a V-a."},{"id":"D","text":"Nu necesită demineralizare suplimentară a smalțului pentru restaurările polimerice de durată."},{"id":"E","text":"Asigură o închidere marginală foarte bună la nivelul smalțului, fără a necesita pași suplimentari."}],"correct":["A"],"pages":[76],"source":"set-2"},{"id":"set2-3VGqjehP","fingerprint":"a7f278056fbd54a9","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce descrie corect abordarea modernă în tratamentul unei cavități medii?","options":[{"id":"A","text":"Se aplică sistemul adeziv direct, fără a utiliza lineri sau baze."},{"id":"B","text":"Se aplică o bază în funcție de distanța până la joncțiunea amelo-dentinară, urmată de sistemul adeziv."},{"id":"C","text":"Sistemul adeziv se aplică doar după interpunerea unui strat de ciment cu ionomer de sticlă modificat cu rășini (CIMR)."},{"id":"D","text":"Este necesară realizarea unui coafaj indirect înainte de aplicarea sistemului adeziv."},{"id":"E","text":"Aplicarea unui liner pasiv rezistent mecanic este obligatorie înainte de sistemul adeziv."}],"correct":["A"],"pages":[76],"source":"set-2"},{"id":"set2-nBuOFrCW","fingerprint":"d9a5ef871ab97b34","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este procedura terapeutică indicată într-o cavitate profundă, indiferent de aspectul dentinei juxta-pulpare?","options":[{"id":"A","text":"Realizarea unui coafaj indirect („indirect pulp capping”)."},{"id":"B","text":"Utilizarea unui sistem adeziv de tip „etch and rinse” fără alt tratament prealabil."},{"id":"C","text":"Aplicarea directă a sistemului adeziv, conform variantei moderne pentru cavități superficiale."},{"id":"D","text":"Aplicarea unei baze de ciment cu ionomer de sticlă și apoi a sistemului adeziv."},{"id":"E","text":"Aplicarea unui liner pasiv, specific variantei clasice de tratament pentru cavități medii."}],"correct":["A"],"pages":[76],"source":"set-2"},{"id":"set2-UnOBPwtP","fingerprint":"2f7e4817068316fb","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Conform protocoalelor descrise, care sunt intervalele de timp corecte pentru următoarele etape clinice?","options":[{"id":"A","text":"Timpul de aplicare prin frecare a adezivului pe structurile dentare este de 15-20 de secunde."},{"id":"B","text":"Polimerizarea straturilor de adeziv se realizează timp de 15-20 de secunde."},{"id":"C","text":"Demineralizarea separată a smalțului („selective etch”) pentru sistemele de generația VI/VII durează aproximativ 10-15 secunde."},{"id":"D","text":"Timpul de aplicare al primerului prin frecare cu microaplicatorul este de 10-15 secunde."},{"id":"E","text":"Polimerizarea straturilor de adeziv se realizează timp de 10-15 de secunde."}],"correct":["B","D"],"pages":[76],"source":"set-2"},{"id":"set2-C9gkoPyc","fingerprint":"c526dd1b481bcb84","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele sunt obiective terapeutice simultane ale coafajului indirect?","options":[{"id":"A","text":"Protecția pulpei față de agenții fizici și chimici."},{"id":"B","text":"Stimularea neodentinogenezei."},{"id":"C","text":"Dezinfectarea plăgii dentinare."},{"id":"D","text":"Realizarea unei legături chimice exclusive cu smalțul marginal."},{"id":"E","text":"Îndepărtarea completă a dentinei afectate pentru a expune dentina sănătoasă."}],"correct":["A","B","C"],"pages":[77],"source":"set-2"},{"id":"set2-CnPK68El","fingerprint":"24078815c200580c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În cazul unei cavități profunde cu un strat de dentină restantă dură de 0,4 mm, care este abordarea modernă de protecție pulpo-dentinară?","options":[{"id":"A","text":"Se aplică o obturație de bază din ciment cu ionomer de sticlă convențional."},{"id":"B","text":"Se aplică sistemul adeziv direct pe dentină, fără a utiliza niciun tip de liner."},{"id":"C","text":"Se aplică doar un liner rezistent mecanic, precum un ciment cu ionomer de sticlă modificat cu rășini (CIMR)."},{"id":"D","text":"Se aplică un liner activ și un liner rezistent mecanic."},{"id":"E","text":"Se aplică un liner activ și o bază care se întinde până în apropierea joncțiunii amelo-dentinare."}],"correct":["D"],"pages":[77],"source":"set-2"},{"id":"set2-sYW-TMUW","fingerprint":"eee22e08c56af22f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt condițiile ce trebuie îndeplinite simultan pentru a aplica tehnica „stepwise” sau „selectivă de îndepărtare” a dentinei necrotice?","options":[{"id":"A","text":"Absența oricărui semn de patologie pulpară sau periapicală, atât clinic, cât și radiologic."},{"id":"B","text":"Pacientul trebuie să poată reveni la controale periodice."},{"id":"C","text":"Existența unui istoric de durere spontană, prelungită."},{"id":"D","text":"Îndepărtarea completă a dentinei necrotice este posibilă fără riscul deschiderii camerei pulpare."},{"id":"E","text":"Dintele trebuie să aibă sensibilitate confirmată."}],"correct":["A","B","E"],"pages":[77],"source":"set-2"},{"id":"set2-AfOT66jZ","fingerprint":"321ef882f13f530b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În prima ședință a tehnicilor 'stepwise' sau 'selective', după prepararea cavității și aplicarea stratului neodentinogenetic, ce material este indicat pentru obturația coronară intermediară și ce roluri îndeplinește?","options":[{"id":"A","text":"Un ciment zinc-oxid eugenol, cu rol antiinflamator și de obturație coronară."},{"id":"B","text":"Un ciment cu ionomer de sticlă modificat cu rășini (CIMR), cu indicație simultană de obturație de bază și obturație coronară."},{"id":"C","text":"O rășină compozită fluidă, cu rol de sigilare dentinară."},{"id":"D","text":"Un liner activ, cu rol de stimulare a neodentinogenezei și de obturație intermediară."},{"id":"E","text":"Un ciment pe bază de silicați de calciu, cu rol exclusiv de liner activ."}],"correct":["B"],"pages":[77],"source":"set-2"},{"id":"set2-_PVTUcGd","fingerprint":"fad380958f8bf6de","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este diferența fundamentală în abordarea celei de-a doua ședințe (în absența semnelor patologice) între tehnica 'stepwise' și tehnica 'selectivă'?","options":[{"id":"A","text":"În tehnica 'stepwise' se îndepărtează toate straturile aplicate inițial și dentina necrotică reziduală, în timp ce în tehnica 'selectivă' se excavează de obicei doar obturația intermediară."},{"id":"B","text":"În tehnica 'stepwise' se păstrează materialele aplicate inițial, pe când în tehnica 'selectivă' se îndepărtează complet."},{"id":"C","text":"În tehnica 'selectivă' se reaplică un nou strat neodentinogenetic, iar în tehnica 'stepwise' nu."},{"id":"D","text":"A doua ședință are loc la 6-9 luni pentru tehnica 'stepwise', în timp ce pentru tehnica 'selectivă' nu este necesară o a doua ședință."},{"id":"E","text":"În ambele tehnici, a doua ședință implică doar aplicarea unui material de restaurare de durată peste CIMR-ul inițial."}],"correct":["A"],"pages":[77],"source":"set-2"},{"id":"set2-BYgoeKPv","fingerprint":"9c6dbee513f4f49c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce caracterizează varianta clasică de tratament într-o singură ședință a unei cavități profunde cu dentină dură la nivel pulpar?","options":[{"id":"A","text":"Utilizarea unui ciment cu ionomer de sticlă modificat cu rășini (CIMR) ca unic material de protecție."},{"id":"B","text":"Aplicarea unui liner activ și a unui liner rezistent mecanic pentru a obține o grosime totală de 2 mm împreună cu dentina."},{"id":"C","text":"Aplicarea sistemului adeziv direct pe dentina dură, urmat de materialul de restaurare de durată."},{"id":"D","text":"Aplicarea unui liner activ și a unei baze care se întinde până în apropierea joncțiunii amelo-dentinare."},{"id":"E","text":"Aplicarea unui liner rezistent mecanic dacă stratul de dentină este mai mare de 0,5 mm."}],"correct":["D"],"pages":[77],"source":"set-2"},{"id":"set2-SCdMzv99","fingerprint":"3c801145a5a4da65","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În contextul unui coafaj indirect realizat într-o singură ședință, pe ce suprafețe poate fi aplicat sistemul adeziv?","options":[{"id":"A","text":"Doar pe linerul rezistent mecanic, fiind contraindicată aplicarea pe linerul activ."},{"id":"B","text":"Pe structurile dure și pe stratul de protecție, dacă acesta este din CIS, CIMR sau materiale pe bază de silicați de calciu."},{"id":"C","text":"Pe orice material de bază, cu excepția materialelor pe bază de silicați de calciu."},{"id":"D","text":"Numai pe smalț pentru a asigura o închidere marginală perfectă."},{"id":"E","text":"Exclusiv pe structurile dure dentare, evitând contactul cu orice material de protecție."}],"correct":["B"],"pages":[77],"source":"set-2"},{"id":"set2-vqX0gjWA","fingerprint":"8c58e51a470be294","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce elemente sunt evaluate în cadrul ședințelor de control periodice după o procedură de coafaj indirect?","options":[{"id":"A","text":"Aspectul radiologic al stratului dentinar de interes"},{"id":"B","text":"Prezența sau absența semnelor patologice clinice și radiologice"},{"id":"C","text":"Integritatea obturației coronare provizorii"},{"id":"D","text":"Sensibilitatea pulpară"},{"id":"E","text":"Apariția durerii"}],"correct":["A","B","D"],"pages":[78],"source":"set-2"},{"id":"set2-Crq3SN9m","fingerprint":"8a613de6665f87e2","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt avantajele principale asociate cu tehnicile stratificate de aplicare a materialelor compozite vâscoase?","options":[{"id":"A","text":"Reducerea contracției de polimerizare"},{"id":"B","text":"Eliminarea riscului de contaminare a straturilor"},{"id":"C","text":"Consum redus de timp clinic"},{"id":"D","text":"Permiterea aplicării de straturi cu grosime de peste 2 mm"},{"id":"E","text":"Capacitatea de a realiza restaurări estetice"}],"correct":["A","E"],"pages":[78],"source":"set-2"},{"id":"set2-ud3pnl8l","fingerprint":"8f5f020f49e28004","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele sunt considerate dezavantaje majore ale tehnicilor stratificate de aplicare a compozitelor vâscoase?","options":[{"id":"A","text":"Contaminarea straturilor"},{"id":"B","text":"Creșterea factorului C"},{"id":"C","text":"Consumul mare de timp"},{"id":"D","text":"Apariția golurilor între straturi"},{"id":"E","text":"Limitarea posibilităților de a realiza restaurări estetice"}],"correct":["A","C","D"],"pages":[78],"source":"set-2"},{"id":"set2-chQsj3g8","fingerprint":"4ae4b39de8a36722","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce regulă importantă trebuie respectată pentru a reduce factorul C în timpul aplicării stratificate a materialelor compozite?","options":[{"id":"A","text":"Refacerea întâi a bazei dentinare pentru toți cuspizii"},{"id":"B","text":"Utilizarea exclusivă a matricelor și penelor transparente"},{"id":"C","text":"Utilizarea tehnicii de refacere cu straturi orizontale"},{"id":"D","text":"Evitarea unirii a doi pereți opuși printr-un singur strat"},{"id":"E","text":"Aplicarea de straturi cu o grosime minimă de 2 mm"}],"correct":["D"],"pages":[78],"source":"set-2"},{"id":"set2-Q5UT8zgy","fingerprint":"568f419e4522e669","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele tehnici de restaurare sunt indicate pentru cavitățile localizate în șanțuri și fosete?","options":[{"id":"A","text":"Tehnica de refacere cu ajutorul unei bile de compozit prepolimerizat"},{"id":"B","text":"Tehnica de refacere centripetă"},{"id":"C","text":"Tehnica de restaurare cu index ocluzal"},{"id":"D","text":"Tehnica de refacere anatomic-stratificată"},{"id":"E","text":"Tehnica de refacere cu straturi oblice"}],"correct":["C","D","E"],"pages":[78],"source":"set-2"},{"id":"set2-lyqaTwBG","fingerprint":"16a721797a8e1510","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce afirmații descriu corect tehnica de refacere centripetă a cavităților proximale pe dinții laterali?","options":[{"id":"A","text":"Procedura începe cu refacerea porțiunii proximale a cavității."},{"id":"B","text":"Se utilizează o bilă de compozit prepolimerizat pentru conformarea ariei de contact."},{"id":"C","text":"Are ca obiectiv transformarea unei cavități de clasa a II-a într-una de clasa I."},{"id":"D","text":"Presupune utilizarea teoretică a unei matrice și a unei pene transparente."},{"id":"E","text":"Penele utilizate trebuie să fie exclusiv din lemn."}],"correct":["A","C"],"pages":[78],"source":"set-2"},{"id":"set2-XZuLFFBN","fingerprint":"b16a24388114a548","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Referitor la tehnica de refacere anatomic-stratificată („successive cusp buildup technique”), care afirmație este adevărată?","options":[{"id":"A","text":"Utilizează straturi orizontale succesive, fiecare fiind împărțit în patru porții triunghiulare."},{"id":"B","text":"Permite refacerea întâi a bazei dentinare pentru toți cuspizii, urmată de aplicarea maselor de smalț."},{"id":"C","text":"Transformă o cavitate de clasa a II-a într-una de clasa I înainte de restaurarea ocluzală."},{"id":"D","text":"Presupune obligatoriu refacerea cuspizilor în ordine, de la cel mai mare la cel mai mic."},{"id":"E","text":"Implică amprentarea inițială a suprafeței ocluzale pentru a crea un conformator."}],"correct":["B"],"pages":[78],"source":"set-2"},{"id":"set2-11kwpl0E","fingerprint":"5ae74aa2f31a5872","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În ce situație clinică este deosebit de utilă tehnica de restaurare cu index ocluzal (stamp technique)?","options":[{"id":"A","text":"Restaurarea suprafețelor cu șanțuri și fosete întrerupte puțin de procesul carios."},{"id":"B","text":"Restaurarea cavităților proximale de clasa a II-a de mari dimensiuni."},{"id":"C","text":"Cazurile ce necesită aplicarea unor straturi orizontale pentru a umple cavitatea."},{"id":"D","text":"Refacerea anatomică a cuspizilor multipli, de la cel mai mic la cel mai mare."},{"id":"E","text":"Situațiile în care se dorește transformarea unei cavități de clasa a II-a într-una de clasa I."}],"correct":["A"],"pages":[78],"source":"set-2"},{"id":"set2-dP2MMwCe","fingerprint":"b36b5ad9708e8bdb","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este obiectivul principal al tehnicii de refacere centripetă utilizată pentru cavitățile proximale ale dinților laterali?","options":[{"id":"A","text":"Refacerea cavității cu ajutorul inserturilor ceramice."},{"id":"B","text":"Transformarea unei cavități de clasa a II-a într-una de clasa I."},{"id":"C","text":"Utilizarea unei bile de compozit prepolimerizat pentru conformarea ariei de contact."},{"id":"D","text":"Aplicarea simultană a materialelor fluide și vâscoase, urmată de o singură fotopolimerizare."},{"id":"E","text":"Aplicarea succesivă de straturi oblice de material compozit."}],"correct":["B"],"pages":[79],"source":"set-2"},{"id":"set2-mtHPUYyd","fingerprint":"3fe59c70fd9f7e26","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce caracteristici descriu corect tehnica „snow plow” pentru restaurarea cavităților proximale?","options":[{"id":"A","text":"Se aplică un strat de compozit fluid de 0,5 mm peste adezivul fotopolimerizat."},{"id":"B","text":"Adezivul, compozitul fluid și compozitul pastă se fotopolimerizează simultan."},{"id":"C","text":"Compozitul fluid este fotopolimerizat imediat după aplicarea sa, înainte de compozitul pastă."},{"id":"D","text":"Întreaga cavitate este umplută exclusiv cu compozit fluid."},{"id":"E","text":"Tehnica implică utilizarea unei bile de compozit prepolimerizat."}],"correct":["A"],"pages":[79],"source":"set-2"},{"id":"set2-IjTRSLd_","fingerprint":"7bad8342e2dac121","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În cazul restaurării unei cavități proximale la un dinte frontal cu ambii pereți, vestibular și oral, întrerupți, care este secvența corectă de aplicare stratificată?","options":[{"id":"A","text":"Se aplică straturi dinspre peretele oral prezent spre creasta distrusă, refăcând succesiv suprafețele."},{"id":"B","text":"Se utilizează tehnici similare celor pentru șanțuri și fosete, aplicând materialul în masă."},{"id":"C","text":"Se aplică un strat central de dentină, apoi se refac simultan suprafața orală și cea proximală, și la final cea vestibulară."},{"id":"D","text":"Se reface întâi suprafața vestibulară, apoi cea orală și în final se aplică un strat central de dentină."},{"id":"E","text":"Se aplică un strat central de dentină, apoi se reface suprafața vestibulară, urmată de cea orală și proximală."}],"correct":["E"],"pages":[79],"source":"set-2"},{"id":"set2-G4IxHmjY","fingerprint":"58787795741d4409","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele afirmații referitoare la tehnicile de restaurare a cavităților cervicale sunt corecte?","options":[{"id":"A","text":"O tehnică presupune aplicarea unui strat inițial, vertical, împărțit în patru porții triunghiulare."},{"id":"B","text":"Straturile de compozit se fotopolimerizează toate simultan la finalul aplicării."},{"id":"C","text":"Tehnica de refacere anatomic-stratificată implică aplicarea unui singur strat oblic."},{"id":"D","text":"Conformatoarele cervicale se folosesc pentru a preveni formarea bulelor de aer în timpul aplicării."},{"id":"E","text":"Se utilizează exclusiv tehnici de aplicare în masă a materialelor compozite."}],"correct":["A"],"pages":[79],"source":"set-2"},{"id":"set2-bSHOWlkC","fingerprint":"3cfaff893d2fca4f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce dezavantaj major prezintă tehnica de aplicare fără contact a materialelor fluide (flow) și cum poate fi acesta prevenit?","options":[{"id":"A","text":"Dezavantajul este timpul de lucru prelungit, prevenit prin utilizarea materialelor cu priză rapidă."},{"id":"B","text":"Dezavantajul este fotopolimerizarea incompletă, prevenită prin utilizarea unei lămpi de mare putere."},{"id":"C","text":"Dezavantajul este formarea de bule de aer, prevenită prin aplicarea materialului în contact tangențial."},{"id":"D","text":"Dezavantajul este apariția de goluri, prevenită prin omogenizarea materialului cu vârful de injectare sau un fuloar."},{"id":"E","text":"Dezavantajul este excesul de material, prevenit prin utilizarea unor vârfuri de seringă mai subțiri."}],"correct":["D"],"pages":[79],"source":"set-2"},{"id":"set2-er0B-h_m","fingerprint":"23f3c8d724905273","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Referitor la compozitele de tip „bulk-fill”, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Aceste materiale sunt disponibile doar sub formă de pastă condensabilă."},{"id":"B","text":"Compozitele „bulk fill body” au, în general, o fluiditate mai scăzută decât cele de bază."},{"id":"C","text":"Compozitele „bulk-fill base” înlocuiesc atât dentina, cât și smalțul pierdut."},{"id":"D","text":"Compozitele „bulk-fill base” sunt caracterizate de o fluiditate mare."},{"id":"E","text":"Se aplică obligatoriu în straturi succesive de maximum 1 mm grosime."}],"correct":["B","D"],"pages":[79],"source":"set-2"},{"id":"set2-l4ojlYc9","fingerprint":"ea212a50d4677fd7","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următorii factori sunt considerați favorizanți pentru obținerea unei închideri marginale corecte?","options":[{"id":"A","text":"Realizarea unui bizou indiferent de prezența forțelor mecanice directe la nivelul acestuia."},{"id":"B","text":"Utilizarea unui sistem adeziv de tip „self-etch”."},{"id":"C","text":"Marginile de smalț sănătos, susținut dentinar și fără anfractuozități."},{"id":"D","text":"Utilizarea unui sistem adeziv de generația a IV-a sau a V-a."},{"id":"E","text":"Prezența unor microfisuri la nivelul marginilor de smalț."}],"correct":["C","D"],"pages":[79],"source":"set-2"},{"id":"set2-U8YdoG2R","fingerprint":"2468439705640639","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce tehnică de aplicare a materialelor compozite este descrisă ca fiind similară cu cea de restaurare cu amalgam de argint?","options":[{"id":"A","text":"Tehnica de refacere centripetă a cavităților proximale."},{"id":"B","text":"Tehnica „injection molded”TM."},{"id":"C","text":"Tehnica de aplicare în masă (bulk) a materialelor de bază (bulk-fill base)."},{"id":"D","text":"Tehnica de aplicare a materialelor condensabile (packable composites)."},{"id":"E","text":"Tehnica de aplicare a materialelor fluide (flow) prin contact tangențial."}],"correct":["D"],"pages":[79],"source":"set-2"},{"id":"set2-eKCg4ktj","fingerprint":"14843fe6cc6c4599","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele metode pot fi utilizate pentru a crește fluiditatea compozitelor cu vâscozitate crescută, în scopul îmbunătățirii adaptabilității acestora?","options":[{"id":"A","text":"Aplicarea în asociere cu un compozit fluid"},{"id":"B","text":"Amestecarea materialului cu o cantitate mică de adeziv dentinar"},{"id":"C","text":"Reducerea timpului de malaxare a materialului"},{"id":"D","text":"Încălzirea materialului înainte de aplicare"},{"id":"E","text":"Utilizarea instrumentelor sonice în timpul aplicării"}],"correct":["A","D","E"],"pages":[80],"source":"set-2"},{"id":"set2-JLsAEHjQ","fingerprint":"b3983925895453ec","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce caracterizează o restaurare de tip „sandwich închis”?","options":[{"id":"A","text":"Materialul de durată utilizat atât subgingival, cât și supragingival este un compozit fluid."},{"id":"B","text":"Constă în obturarea unei preparații medii sau profunde cu evoluție supragingivală."},{"id":"C","text":"Linerul/baza subiacentă este acoperit parțial de materialul de restaurare de durată."},{"id":"D","text":"Este o tehnică utilizată în cavități cu evoluție subgingivală."},{"id":"E","text":"Este contraindicată asocierea cu un liner sau o bază din CIS/CIMR."}],"correct":["B"],"pages":[80],"source":"set-2"},{"id":"set2-KEl3rtFV","fingerprint":"81ea438a32be80da","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele afirmații descrie corect o restaurare de tip „sandwich deschis”?","options":[{"id":"A","text":"Este specifică pentru cavități cu evoluție juxtagingivală."},{"id":"B","text":"Materialul de restaurare subgingival este CIMR, iar cel supragingival este un material de durată aderent."},{"id":"C","text":"Se realizează prin acoperirea totală a preparației cu ciment ionomer de sticlă modificat cu rășini (CIMR)."},{"id":"D","text":"Linerul/baza din CIS/CIMR este acoperit în totalitate de materialul de durată."},{"id":"E","text":"Utilizează același material de restaurare de durată atât în porțiunea subgingivală, cât și în cea supragingivală."}],"correct":["B"],"pages":[80],"source":"set-2"},{"id":"set2-VA00JHPA","fingerprint":"b3e4a5366b13ccc6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce materiale sunt indicate pentru tehnica de aplicare anatomic stratificată în cavitățile mici de clasa I?","options":[{"id":"A","text":"Rășini compozite condensabile"},{"id":"B","text":"Compomeri"},{"id":"C","text":"Cimenturi ionomere de sticlă modificate cu rășini (CIMR)"},{"id":"D","text":"Polisticle"},{"id":"E","text":"Giomeri"}],"correct":["B","C","E"],"pages":[80],"source":"set-2"},{"id":"set2-xTAUE_ki","fingerprint":"a37dca99e11f656e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În cazul restaurării cavităților medii/mari de clasa I prin aplicare anatomic stratificată, ce materiale de durată sunt indicate pentru a asigura o rezistență mecanică mare?","options":[{"id":"A","text":"Variante de tip fluid ale rășinilor compozite"},{"id":"B","text":"Compomeri"},{"id":"C","text":"Rășini compozite \"low-shrink\""},{"id":"D","text":"Polisticle"},{"id":"E","text":"Giomeri condensabili"}],"correct":["C","D","E"],"pages":[80],"source":"set-2"},{"id":"set2-Beq6qWOw","fingerprint":"3f56f00e8c1ea66e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele materiale sunt specific menționate pentru tehnica de aplicare în masă („bulk”)?","options":[{"id":"A","text":"Compomeri"},{"id":"B","text":"Cimenturi ionomere de sticlă (CIS) armate autopolimerizabile"},{"id":"C","text":"Rășini compozite „bulk”"},{"id":"D","text":"Ceromeri"},{"id":"E","text":"Ormoceri"}],"correct":["B","C"],"pages":[80],"source":"set-2"},{"id":"set2-hefMqryE","fingerprint":"0d89b9fa7783404f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile esențiale ale unei restaurări aderente considerate corespunzătoare?","options":[{"id":"A","text":"Relief morfologic și funcțional"},{"id":"B","text":"Închidere marginală corectă"},{"id":"C","text":"Utilizarea tehnicii „stamp” pentru modelarea ocluzală"},{"id":"D","text":"Culoare corectă"},{"id":"E","text":"Aplicarea materialului într-un singur strat orizontal între pereții opuși"}],"correct":["A","B","D"],"pages":[80],"source":"set-2"},{"id":"set2-sLLjNrzf","fingerprint":"ea0a4adf7bfa7a85","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte referitoare la caracteristicile matricelor metalice utilizate în restaurările proximale din zona laterală?","options":[{"id":"A","text":"Augmentează fotopolimerizarea acționând ca niște oglinzi."},{"id":"B","text":"Pot fi brunisate pentru a conforma viitoarea arie de contact."},{"id":"C","text":"Permit grosimi foarte reduse."},{"id":"D","text":"Se deformează ușor în timpul manevrării."},{"id":"E","text":"Sunt transparente, permițând vizualizarea directă a materialului."}],"correct":["A","B","C"],"pages":[81],"source":"set-2"},{"id":"set2-_uV618HH","fingerprint":"c748c4bb81d25a3d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este poziționarea corectă a unei matrice dentare după aplicare, în raport cu reperele anatomice adiacente?","options":[{"id":"A","text":"Matricea trebuie să depășească cu 2 mm, în sens apical, pragul gingival și cu 1 mm, în sens ocluzal, creasta marginală vecină."},{"id":"B","text":"Matricea trebuie să fie plasată strict între pragul gingival și creasta marginală vecină, fără a le depăși."},{"id":"C","text":"Matricea trebuie să fie la același nivel cu pragul gingival și să depășească cu 2 mm creasta marginală vecină."},{"id":"D","text":"Matricea trebuie să depășească cu 1 mm, în sens apical, pragul gingival și cu 1 mm, în sens ocluzal, creasta marginală vecină."},{"id":"E","text":"Matricea trebuie să depășească cu 1 mm, în sens apical, pragul gingival și să fie la același nivel cu creasta marginală vecină."}],"correct":["D"],"pages":[81],"source":"set-2"},{"id":"set2-KuFnR9Oz","fingerprint":"e2b060554aa3bde0","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce tehnică de aplicare a penelor este indicată în situația unei anatomii accentuat concave la nivel cervical?","options":[{"id":"A","text":"Aplicarea unei singure pene dinspre nișa orală."},{"id":"B","text":"„Double wedging technique”"},{"id":"C","text":"Aplicarea subgingivală a unei benzi de teflon."},{"id":"D","text":"„Wedge wedging technique”"},{"id":"E","text":"„Piggyback wedging technique”"}],"correct":["D"],"pages":[81],"source":"set-2"},{"id":"set2-9uayxnEb","fingerprint":"05080029a349f3ae","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Conform cărui criteriu se face alegerea dimensiunii penei dentare utilizate în restaurarea cariilor proximale?","options":[{"id":"A","text":"De grosimea matricei utilizate."},{"id":"B","text":"De tehnica de restaurare aleasă (stratificată sau în masă)."},{"id":"C","text":"De tipul de material de restaurare (pastă sau fluid)."},{"id":"D","text":"De adâncimea cavității în sens pulpar."},{"id":"E","text":"De vizibilitatea restaurării."}],"correct":["A"],"pages":[81],"source":"set-2"},{"id":"set2-9x7SpF8W","fingerprint":"b58d8fabe037cd8d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce materiale de restaurare pot fi utilizate pentru cavitățile fără deschidere ocluzală de tip „galerie” și „casetă modificată pentru materiale aderente”?","options":[{"id":"A","text":"Doar materiale cu consistență de pastă, excluzând variantele fluide."},{"id":"B","text":"Rășini compozite de tip „bulk” și „low-shrink”."},{"id":"C","text":"Compomeri și giomeri."},{"id":"D","text":"Cimenturi cu ionomeri de sticlă (CIS) armate autopolimerizabile și cimenturi ionomere de sticlă modificate cu rășini (CIMR)."},{"id":"E","text":"Ceromeri și ormoceri."}],"correct":["B","C","D","E"],"pages":[81],"source":"set-2"},{"id":"set2-E4XnwFOp","fingerprint":"b8df4194787318ce","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În ce situație clinică este recomandată tehnica „double wedging”?","options":[{"id":"A","text":"La o evazare mică a pereților verticali ai cavității."},{"id":"B","text":"Pentru restaurările de tip „tunel” fără deschidere ocluzală."},{"id":"C","text":"În cazul unei anatomii cervicale accentuat concave."},{"id":"D","text":"În cazul evoluțiilor carioase subgingivale."},{"id":"E","text":"Când deschiderea cavității este mai mare decât zona ariei de contact."}],"correct":["E"],"pages":[81],"source":"set-2"},{"id":"set2-Qfq7XlcW","fingerprint":"e9ad61808703a829","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce materiale sunt indicate pentru obturarea porțiunii de smalț proximal și a zonei dentinare în cazul cavităților de tip „tunel”?","options":[{"id":"A","text":"Rășini compozite clasice condensabile în straturi de maxim 2 mm."},{"id":"B","text":"Compozite de tip „bulk” aplicate în strat unic."},{"id":"C","text":"Cimenturi cu ionomer de sticlă (CIS) armate."},{"id":"D","text":"Variante fluide de ormocer, rășină compozită, giomer sau compomer."},{"id":"E","text":"Compozit fluid autogravant sau ciment cu ionomer de sticlă modificat cu rășini (CIMR)."}],"correct":["D","E"],"pages":[82],"source":"set-2"},{"id":"set2-pM4rnBa-","fingerprint":"efb0c5f311f4ec18","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este cea mai importantă regulă în tehnica de aplicare anatomic stratificată a materialelor de restaurare?","options":[{"id":"A","text":"Ultimul strat proximal trebuie fotopolimerizat imediat după aplicare, înainte de conformarea ariei de contact."},{"id":"B","text":"Primul strat aplicat la nivelul peretelui gingival trebuie să fie întotdeauna gingivo-oral."},{"id":"C","text":"Este obligatoriu ca fiecare strat să aibă o grosime mai mare de 2 mm pentru a asigura rezistența mecanică."},{"id":"D","text":"Straturile aplicate nu trebuie să unească pereții opuși, iar materialul să fie aplicat în secțiune triunghiulară/trapezoidală."},{"id":"E","text":"Se aplică un singur strat orizontal care umple întreaga componentă proximală dintr-o dată."}],"correct":["D"],"pages":[82],"source":"set-2"},{"id":"set2-nwKsjK3A","fingerprint":"3fb7f8912535e77b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații, referitoare la restaurarea cavităților cu deschidere ocluzală, descriu corect materialele și tehnica de aplicare în masă („bulk”) supragingivală?","options":[{"id":"A","text":"Modelarea stratului superficial se realizează exclusiv cu instrumente rotative după priza materialului."},{"id":"B","text":"Fizionomia crescută este considerată o cerință secundară."},{"id":"C","text":"Exemple de materiale sunt compozitele de tip „bulk” și cimenturile cu ionomer de sticlă armate."},{"id":"D","text":"Aceste materiale necesită, în principal, rezistență mecanică foarte bună."},{"id":"E","text":"Pot fi aplicate în strat unic cu o grosime mai mare de 2 mm."}],"correct":["B","C","D","E"],"pages":[82],"source":"set-2"},{"id":"set2-VnLN2jQu","fingerprint":"947fae8dc684778d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Indiferent de tehnica aleasă pentru porțiunea supragingivală, care este materialul de elecție pentru restaurarea porțiunii subgingivale a unei cavități?","options":[{"id":"A","text":"Ceromeri sau ormoceri."},{"id":"B","text":"Rășini compozite de tip „low-shrink”."},{"id":"C","text":"Compozite de tip „bulk”."},{"id":"D","text":"Giomer condensabil."},{"id":"E","text":"Cimenturi cu ionomer de sticlă modificate cu rășini (CIMR)."}],"correct":["E"],"pages":[82],"source":"set-2"},{"id":"set2-SrQtdqhI","fingerprint":"17c49a2684a29970","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În ce condiții se decide unirea sau separarea cavităților proximale și ocluzale care coexistă pe același dinte?","options":[{"id":"A","text":"În prezența cariilor ocluzale cu orificiu mic, cavitățile se unesc întotdeauna pentru a crea o cavitate mezio-ocluzo-distală."},{"id":"B","text":"Cavitățile nu se vor uni dacă între ele există punți de structură dură sănătoasă mai groase de 1-1,5 mm, în cazul coexistenței cu carii ocluzale cu orificiu mic de deschidere."},{"id":"C","text":"Cavitățile se vor uni dacă între ele există punți de structură dură sănătoasă mai subțiri de 1 mm, în cazul coexistenței cu carii ocluzale cu orificii mari de deschidere."},{"id":"D","text":"În prezența cariilor ocluzale cu orificii mari, cavitățile nu se unesc niciodată, păstrându-se separate."},{"id":"E","text":"Prepararea cavităților pentru ambele fețe proximale se va efectua simultan pentru a asigura o unire corectă."}],"correct":["B","C"],"pages":[82],"source":"set-2"},{"id":"set2-Uhyae0Cy","fingerprint":"5a6fc618381e06c5","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce presupune „tehnica de alternare a penelor” în cursul restaurării a două fețe proximale adiacente folosind o matrice circulară?","options":[{"id":"A","text":"Se aplică simultan două pene în ambele nișe gingivale pentru a stabiliza matricea pe parcursul întregii proceduri."},{"id":"B","text":"Prima pană este introdusă, se restaurează prima suprafață, apoi pana este îndepărtată și o nouă pană este introdusă în cealaltă nișă pentru a restaura a doua suprafață."},{"id":"C","text":"Componenta ocluzală se restaurează întotdeauna înainte de aplicarea penelor și restaurarea fețelor proximale."},{"id":"D","text":"Se utilizează o singură pană, care se alternează între cele două nișe, fără a se îndepărta complet de pe câmpul operator."},{"id":"E","text":"Matricea circulară este îndepărtată după restaurarea primei fețe proximale și apoi repoziționată pentru a doua față."}],"correct":["B"],"pages":[82],"source":"set-2"},{"id":"set2-SVhHtMO4","fingerprint":"5cfdd46d9774b529","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În ceea ce privește restaurarea cavităților de clasa a II-a modificate cu materiale aderente, cu deschidere ocluzală, care sunt caracteristicile materialelor utilizate supragingival prin tehnica de aplicare anatomic stratificată?","options":[{"id":"A","text":"Exemple de astfel de materiale includ rășini compozite clasice, condensabile, ceromeri și ormoceri."},{"id":"B","text":"Principala cerință pentru aceste materiale este rezistența mecanică foarte bună."},{"id":"C","text":"Se pot utiliza exclusiv compozite de tip „bulk” și cimenturi cu ionomer de sticlă armate."},{"id":"D","text":"Fizionomia crescută este considerată o cerință principală, mai importantă decât rezistența mecanică."},{"id":"E","text":"Se aplică în straturi cu o grosime de maxim 2 mm."}],"correct":["A","B","E"],"pages":[82],"source":"set-2"},{"id":"set2-sNLldiMz","fingerprint":"f7c0d618e01df097","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Cu privire la secvența de restaurare în cazul cariilor pe ambele fețe proximale, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Componenta ocluzală extinsă se restaurează de obicei ultima, după îndepărtarea sistemului de matrice."},{"id":"B","text":"Se recomandă ca aplicarea materialului de restaurare să se facă întâi pentru o porțiune proximală, iar apoi pentru cealaltă."},{"id":"C","text":"Toate componentele, proximale și ocluzală, trebuie restaurate înainte de îndepărtarea finală a matricei."},{"id":"D","text":"Etapa ortopedică începe frecvent cu restaurarea feței meziale."},{"id":"E","text":"Se pot utiliza două matrice parțiale sau o matrice circulară, dar penele se aplică întotdeauna simultan."}],"correct":["A","B"],"pages":[82],"source":"set-2"},{"id":"set2-i7_28B2I","fingerprint":"09dd2bedc8eb89cf","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații despre matricele (conformatoarele) utilizate în restaurarea cavităților din zona frontală sunt corecte?","options":[{"id":"A","text":"Se utilizează exclusiv matrice metalice special concepute pentru dinții frontali."},{"id":"B","text":"Toate matricele standardizate sunt realizate din celuloid."},{"id":"C","text":"Benzile de celuloid drepte sau conformate sunt exemple de matrice standardizate."},{"id":"D","text":"Hemicapalele sunt considerate un tip de matrice standardizată."},{"id":"E","text":"Pot fi individualizate prin tehnica mock-up sau wax-up."}],"correct":["C","D","E"],"pages":[83],"source":"set-2"},{"id":"set2-nhwNhJ8L","fingerprint":"13eeb53d302c849a","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce afirmație descrie corect aplicarea penelor în restaurarea cariilor proximale frontale?","options":[{"id":"A","text":"Aplicarea vestibulară este obligatorie indiferent de materialul de restaurare utilizat."},{"id":"B","text":"Se utilizează exclusiv pene din lemn pentru o adaptare cervicală perfectă."},{"id":"C","text":"Se aplică, frecvent, dinspre vestibular datorită accesului și vizibilității crescute."},{"id":"D","text":"Sunt întotdeauna opace pentru a bloca lumina de polimerizare și a proteja țesuturile moi."},{"id":"E","text":"Aplicarea se face întotdeauna dinspre palatinal/lingual pentru a asigura o mai bună stabilitate."}],"correct":["C"],"pages":[83],"source":"set-2"},{"id":"set2-wtAfRs8-","fingerprint":"96e754ea155db94b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt cerințele și exemplele de materiale de restaurare utilizabile în tehnica de aplicare stratificată pentru cavitățile de clasa a III-a/a IV-a?","options":[{"id":"A","text":"Se utilizează exclusiv materiale cu fluiditate mare pentru o mai bună adaptare."},{"id":"B","text":"Compozitele „bulk” sunt recomandate datorită timpului de lucru redus."},{"id":"C","text":"Necesită fizionomie foarte bună și rezistență mecanică medie sau mare."},{"id":"D","text":"Cimentul cu ionomer de sticlă modificat cu rășini (CIMR) este de elecție pentru întreaga restaurare."},{"id":"E","text":"Printre materialele utilizabile se numără rășinile compozite clasice, ceromerii și ormocerii."}],"correct":["C","E"],"pages":[83],"source":"set-2"},{"id":"set2-I_3rPa2_","fingerprint":"aa668db7f93d4135","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În cazul restaurării unei cavități de clasa a IV-a cu evoluție subgingivală, ce material este indicat pentru porțiunea subgingivală a restaurării de durată?","options":[{"id":"A","text":"Un ciment cu ionomer de sticlă (CIS) clasic."},{"id":"B","text":"Un ciment cu ionomer de sticlă modificat cu rășini (CIMR)."},{"id":"C","text":"Un ormocer tip pastă."},{"id":"D","text":"O rășină compozită fluidă."},{"id":"E","text":"Un compozit „bulk”."}],"correct":["B"],"pages":[83],"source":"set-2"},{"id":"set2-HMXgKpZr","fingerprint":"60af0d42e6ad876c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt criteriile principale de alegere a materialelor de durată pentru restaurarea cavităților de clasa a V-a?","options":[{"id":"A","text":"Rezistență mecanică foarte mare la acțiunea forțelor directe."},{"id":"B","text":"Fluiditate scăzută pentru a preveni refluarea din cavitate."},{"id":"C","text":"Elasticitate crescută, specifică în general materialelor cu fluiditate mare."},{"id":"D","text":"Culoare opacă pentru a masca dentina subiacentă."},{"id":"E","text":"Necesită fizionomie crescută dacă tratamentul se realizează la nivelul dinților frontali."}],"correct":["C","E"],"pages":[83],"source":"set-2"},{"id":"set2-oGJCZJ2w","fingerprint":"38c82c07fdbbd2fd","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce deosebiri există între materialele de elecție pentru tehnica de aplicare stratificată a restaurărilor de clasa a V-a, în funcție de localizarea în zona frontală versus cea laterală?","options":[{"id":"A","text":"În zona frontală, de elecție, sunt indicate variantele cu fluiditate mare ale materialelor aderente fizionomice."},{"id":"B","text":"În zona frontală, se preferă CIS și CIMR, iar în zona laterală, rășini compozite fluide."},{"id":"C","text":"Elasticitatea crescută este un criteriu important doar pentru zona laterală."},{"id":"D","text":"În zona laterală, rezistența mecanică necesară este foarte mare, spre deosebire de zona frontală."},{"id":"E","text":"În zona frontală primează fizionomia, în timp ce în zona laterală acest aspect nu este prioritar."}],"correct":["A","E"],"pages":[83],"source":"set-2"},{"id":"set2-Dpk3Lbxh","fingerprint":"bd43e0387b6de10f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte privind aplicarea în masă („bulk”) a materialelor de restaurare în cavitățile de clasa a V-a?","options":[{"id":"A","text":"Materialele indicate în zona laterală pentru această tehnică includ CIS, clasice și armate, și unele CIMR."},{"id":"B","text":"Cimenturile cu ionomeri de sticlă (CIS) sunt indicate în zona frontală datorită fizionomiei lor reduse."},{"id":"C","text":"Compozitele „bulk” sunt de elecție în zona frontală datorită fizionomiei lor superioare."},{"id":"D","text":"În zona laterală, se pot obtura cavități de orice extindere (mică, medie, mare) deoarece nu există exigențe fizionomice."},{"id":"E","text":"În zona frontală, această tehnică se poate aplica doar pentru cavități cu extindere mică."}],"correct":["A","D","E"],"pages":[83],"source":"set-2"},{"id":"set2-EEUcxRK0","fingerprint":"50cf311317665386","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt rolurile de bază ale matricelor cervicale în restaurările dentare?","options":[{"id":"A","text":"Conformarea morfologică și funcțională a materialului de restaurare."},{"id":"B","text":"Obținerea unui strat superficial de compozit cu proprietăți optime prin facilitarea fotopolimerizării în absența oxigenului."},{"id":"C","text":"Previn refluarea materialului în toate situațiile clinice."},{"id":"D","text":"Retenționarea materialului de restaurare, în special dacă acesta este fluid."},{"id":"E","text":"Aplicarea lor este obligatorie la utilizarea materialelor de restaurare de tip pastă."}],"correct":["A","B","D"],"pages":[84],"source":"set-2"},{"id":"set2-ysv63nMH","fingerprint":"2b76aa3a21ce5a2d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce recomandare specifică există în legătură cu finisarea de finețe și lustruirea materialelor compozite moderne?","options":[{"id":"A","text":"Sunt obligatorii pentru a permite compozitului să atingă rata de conversie maximă."},{"id":"B","text":"Există studii care susțin că ar trebui realizate la cel puțin 24 de ore de la aplicare."},{"id":"C","text":"Se recomandă a fi executate numai în situații de strictă necesitate."},{"id":"D","text":"Utilizarea unui lac protector imediat după lustruire este obligatorie."},{"id":"E","text":"Sunt manevre esențiale care trebuie efectuate imediat după fotopolimerizare pentru a preveni microfracturile."}],"correct":["B","C"],"pages":[84],"source":"set-2"},{"id":"set2-oAtGk3NP","fingerprint":"a01a001d66bd5f02","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici descriu un sigilant de suprafață („surface sealant”) utilizat pentru materialele compozite?","options":[{"id":"A","text":"Aplicarea sa peste materialele compozite este obligatorie."},{"id":"B","text":"Este un produs pe bază de monomer fără umplutură și solvent."},{"id":"C","text":"Trebuie reîmprospătat la un interval de aproximativ 24 de luni."},{"id":"D","text":"Are rolul de a umple microfisurile produse de finisare și lustruire."},{"id":"E","text":"Este identic cu lacul protector aplicat peste cimenturile cu ionomeri de sticlă."}],"correct":["B","D"],"pages":[84],"source":"set-2"},{"id":"set2-bH1fEbRE","fingerprint":"412a64f1b140b5d4","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este atitudinea terapeutică corectă în fața diferitelor tipuri de defecte ale unei restaurări de compozit?","options":[{"id":"A","text":"Defectele limitate ale închiderii marginale impun realizarea unor preparații minime, localizate."},{"id":"B","text":"Apariția unor segmente de smalț marginal albicios nu este considerată un defect, ci o consecință normală a procedurii."},{"id":"C","text":"Defectele mari necesită doar reîmprospătarea sigilantului de suprafață la fiecare 6 luni."},{"id":"D","text":"Orice defect, indiferent de dimensiune, necesită îndepărtarea completă și înlocuirea obturației."},{"id":"E","text":"Defectele mari, cum ar fi golurile de dimensiuni considerabile, pot fi corectate prin aplicarea unui sigilant de suprafață."}],"correct":["A"],"pages":[84],"source":"set-2"},{"id":"set2-qhM0VvDl","fingerprint":"337a8ba1d5cd1fee","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce metodă este recomandată pentru a obține un strat superficial de compozit cu proprietăți optime în situația în care acesta nu este acoperit de o matrice?","options":[{"id":"A","text":"Se realizează o fotopolimerizare suplimentară după verificarea ocluziei."},{"id":"B","text":"Stratul final de compozit se protejează cu un strat de gel transparent cu glicerină înainte de fotopolimerizare."},{"id":"C","text":"Se aplică un sigilant de suprafață pe bază de monomer înainte de fotopolimerizarea finală."},{"id":"D","text":"Se recomandă finisarea imediată cu instrumentar rotativ pentru a elimina stratul inhibat de oxigen."},{"id":"E","text":"Se aplică un lac protector pe bază de CIS înainte de fotopolimerizare."}],"correct":["B"],"pages":[84],"source":"set-2"},{"id":"set2-Gy7wSUZ1","fingerprint":"541b5cb84efe67e0","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este o regulă esențială de compatibilitate la aplicarea unui material rășinic nou peste o restaurare existentă?","options":[{"id":"A","text":"Dacă nu se cunoaște materialul inițial, aplicarea unui strat gros de adeziv asigură compatibilitatea."},{"id":"B","text":"Compozitele cu silorani pot fi aplicate peste cele pe bază de metacrilat, dar nu și invers."},{"id":"C","text":"Compozitele pe bază de metacrilat pot fi aplicate peste cele cu silorani, dar nu și invers."},{"id":"D","text":"Nu se aplică compozite pe bază de metacrilat peste cele cu silorani și invers."},{"id":"E","text":"Orice tip de material rășinic nou este compatibil cu cel inițial dacă se utilizează un adeziv universal."}],"correct":["D"],"pages":[85],"source":"set-2"},{"id":"set2-JL0K0m5k","fingerprint":"60f8857cecf6937a","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații sunt corecte în legătură cu tratamentul aderent direct al cariilor secundare?","options":[{"id":"A","text":"La îndepărtarea amalgamului, cavitățile rezultate sunt restrânse pentru a conserva structura dentară."},{"id":"B","text":"Protocolul de lucru implică o etapă suplimentară de îndepărtare mecanică a materialului de restaurare vechi."},{"id":"C","text":"Noile cavități sunt de obicei mai mici decât preparațiile inițiale datorită tehnicilor minim invazive."},{"id":"D","text":"Interiorul noilor cavități trebuie să prezinte un aspect rotunjit, indiferent de materialul înlocuit."},{"id":"E","text":"Cavitățile rezultate sunt de obicei mai mari din cauza îndepărtării suplimentare de smalț demineralizat și dentină necrotică."}],"correct":["B","D","E"],"pages":[85],"source":"set-2"},{"id":"set2-hxg7BRSI","fingerprint":"14b42582a41895b6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce caracteristici specifice prezintă cavitățile rezultate în urma îndepărtării restaurărilor de amalgam, în vederea înlocuirii cu materiale aderente?","options":[{"id":"A","text":"Sunt extinse, deretentivizate și cu interior rotunjit."},{"id":"B","text":"Sunt extinse, dar păstrează caracterul retentiv pentru a susține noul material."},{"id":"C","text":"Păstrează forma de retenție a preparației inițiale."},{"id":"D","text":"Sunt restrânse, retentive și cu unghiuri ascuțite."},{"id":"E","text":"Au un interior neregulat pentru a crește aderența mecanică."}],"correct":["A"],"pages":[85],"source":"set-2"},{"id":"set2-mAZtEbkR","fingerprint":"5580dcbf828b9640","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care afirmații descriu corect contextul apariției leziunilor carioase ce necesită prepararea unor cavități de clasa a VI-a?","options":[{"id":"A","text":"În cazul atriției, smalțul se uzează mai repede decât dentina, creând o suprafață convexă protectoare."},{"id":"B","text":"Sunt rezultatul direct al unor leziuni necarioase, cum ar fi atriția, care modifică morfologia suprafeței dentare."},{"id":"C","text":"Apar pe suprafețe care în mod natural favorizează retenția plăcii bacteriene, cum ar fi șanțurile și fosetele."},{"id":"D","text":"Sunt cauzate exclusiv de leziuni distrofice, fără implicarea atriției."},{"id":"E","text":"Apariția lor este favorizată de crearea unui relief concav pe vârfurile cuspizilor sau marginile incizale, propice retenției plăcii bacteriene."}],"correct":["B","E"],"pages":[85],"source":"set-2"},{"id":"set2-vDQ0jjmE","fingerprint":"08198d772f9b0494","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile preparării și restaurării cavităților de clasa a VI-a?","options":[{"id":"A","text":"Bizotarea marginilor este o etapă obligatorie pentru a asigura închiderea marginală."},{"id":"B","text":"Materialele de restaurare trebuie să aibă rezistență mecanică mare și fizionomie foarte bună (mai ales când sunt implicate muchiile incizale)."},{"id":"C","text":"Prepararea se realizează frecvent cu freze sferice la turație redusă."},{"id":"D","text":"Sunt cavități adânci, pereții juxtapulpari fiind frecvent foarte apropiați de camera pulpară."},{"id":"E","text":"Datorită localizării în zone funcționale, necesită adesea retenție suplimentară, cum ar fi pinii parapulpari."}],"correct":["B","C","E"],"pages":[85],"source":"set-2"},{"id":"set2-e74Jkxu3","fingerprint":"b3d737babb31a576","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce tipuri de materiale de restaurare sunt recomandate pentru cavitățile de clasa a VI-a?","options":[{"id":"A","text":"Ormoceri."},{"id":"B","text":"Amalgam, datorită rezistenței mecanice superioare."},{"id":"C","text":"Compozite fluide, pentru o adaptare marginală superioară."},{"id":"D","text":"Cimenturi cu ionomer de sticlă convenționale."},{"id":"E","text":"Rășini compozite hibride."}],"correct":["A","E"],"pages":[85],"source":"set-2"},{"id":"set2-KG78naEB","fingerprint":"100470ccbf17bcb5","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele proceduri sunt incluse în etapele preliminarii ale tratamentului aderent direct pentru cariile simple cavitare?","options":[{"id":"A","text":"Introducerea unei protecții pentru dintele vecin pentru cariile proximale fără acces direct."},{"id":"B","text":"Realizarea sigilării dentinare și a protecției pulpare."},{"id":"C","text":"Efectuarea obligatorie a anesteziei locale pentru toate tipurile de leziuni."},{"id":"D","text":"Separarea rapidă prealabilă cu ajutorul unor pene dentare în cazul cariilor proximale."},{"id":"E","text":"Marcarea stopurilor ocluzale în mod obligatoriu pentru cariile cervicale."}],"correct":["A","D"],"pages":[68,69],"source":"set-2"},{"id":"set2-v35ucNhY","fingerprint":"09f6e794f9f7d2fe","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele tehnici generale de îndepărtare a țesutului carios nu se mai folosește în practica actuală?","options":[{"id":"A","text":"Îndepărtarea în trepte („stepwise”) a țesutului carios în două etape."},{"id":"B","text":"Îndepărtarea selectivă a țesutului carios până în dentină afectată."},{"id":"C","text":"Îndepărtarea selectivă a țesutului carios până în dentină necrotică."},{"id":"D","text":"Îndepărtarea parțială limitată exclusiv la smalțul demineralizat de la nivelul marginii cavosuprafeței."},{"id":"E","text":"Îndepărtarea neselectivă a țesutului carios până în dentină dură, cu aspect normal."}],"correct":["E"],"pages":[68,69],"source":"set-2"},{"id":"set2-UyjdH13W","fingerprint":"ffbf8479d8a92600","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile dentinei afectate, a cărei menținere este permisă în timpul preparării cavităților pentru materiale aderente?","options":[{"id":"A","text":"Este dură, demineralizată și pigmentată."},{"id":"B","text":"Are o încărcătură bacteriană mare, motiv pentru care necesită menținere selectivă."},{"id":"C","text":"Prezintă o încărcătură bacteriană redusă."},{"id":"D","text":"Este complet distrusă din punct de vedere arhitectural."},{"id":"E","text":"Prezintă o arhitectură tisulară nedistrusă."}],"correct":["A","C","E"],"pages":[68,69],"source":"set-2"},{"id":"set2-UL6CX6rU","fingerprint":"8c233678b4b77d8e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce caracteristici principale definesc cavitățile modificate pentru materiale aderente, obținute prin aplicarea principiilor minim invazive?","options":[{"id":"A","text":"Creste marginale ocluzale restante cu o grosime cuprinsă între 1,5 și 2 mm, acolo unde situația clinică impune."},{"id":"B","text":"Unghiuri între pereții interni și exterior (unghiuri de cavosuprafață) strict sub 90 de grade."},{"id":"C","text":"O configurație internă rotunjită."},{"id":"D","text":"Efectuarea sistematică a bizotării, indiferent de intensitatea forțelor ocluzale directe."},{"id":"E","text":"Prezența unor margini fără anfractuozități."}],"correct":["A","C","E"],"pages":[68,69],"source":"set-2"},{"id":"set2-Ujdkb0I6","fingerprint":"e14020215cf48381","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce instrumentar este indicat pentru etapa de instrumentare finală (finisarea) a marginilor cavității preparate?","options":[{"id":"A","text":"Sonoabraziunea."},{"id":"B","text":"Instrumente abrazive diamantate sau nediamantate."},{"id":"C","text":"Freze extradure cu lamele dese."},{"id":"D","text":"Freze polimerice."},{"id":"E","text":"Instrumentar specific pentru abraziunea cu aer."}],"correct":["A","B","C"],"pages":[68,69],"source":"set-2"},{"id":"set2-QSL-_e3U","fingerprint":"fc4a81533415e1e6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile preparației în cazul cariilor cavitare cu orificiu mic de deschidere, localizate în șanțuri și fosete, modificate pentru materiale aderente?","options":[{"id":"A","text":"Prezența unei configurații interne rotunjite"},{"id":"B","text":"Marginile netede, fără anfractuozități"},{"id":"C","text":"Existența unei cantități masive de dentină necrotică"},{"id":"D","text":"Bizotarea marginilor în zonele supuse direct forțelor mecanice"},{"id":"E","text":"Evoluția în profunzime direct proporțională cu gradul de deschidere de la nivelul smalțului"}],"correct":["A","B"],"pages":[69],"source":"set-2"},{"id":"set2-E_tr2GKm","fingerprint":"3571b94701f4e8fe","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt reperele și caracteristicile aspectului final al preparațiilor pentru cariile cu orificiu mediu și mare de deschidere, în vederea aplicării materialelor aderente?","options":[{"id":"A","text":"Configurația internă prezintă un aspect exclusiv plan, complet lipsit de denivelări."},{"id":"B","text":"Lățimea crestelor marginale trebuie să fie de minim 1,5 mm la premolari."},{"id":"C","text":"Lățimea crestelor marginale este de minim 2 mm la molari."},{"id":"D","text":"Șanțurile învecinate cavității preparate care prezintă colorații sunt înglobate în conturul total marginal."},{"id":"E","text":"Unghiurile formate de pereții interni cu suprafața sunt menținute la o valoare strict mai mică de 90°."}],"correct":["B","C","D"],"pages":[69],"source":"set-2"},{"id":"set2-nJjPJ9TK","fingerprint":"b4a5dfd7c6db0605","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce particularități prezintă abordarea țesuturilor dure dentare și evaluarea inițială în cazul cariilor cu orificiu mediu și mare de deschidere?","options":[{"id":"A","text":"Îndepărtarea smalțului nesusținut este obligatorie pentru asigurarea retenției mecanice."},{"id":"B","text":"Smalțul subminat poate fi menținut în cavitate și căptușit prin utilizarea materialelor aderente moderne."},{"id":"C","text":"Profunzimea procesului carios nu poate fi apreciată orientativ în etapa clinică inițială."},{"id":"D","text":"Țesuturile care nu mai pot fi conservate sunt reprezentate de smalțul demineralizat și dentina necrotică."},{"id":"E","text":"Păstrarea unei cantități importante de smalț subminat în prezența forțelor ocluzale mari impune o abordare precaută."}],"correct":["B","D","E"],"pages":[69],"source":"set-2"},{"id":"set2-dRty-1ly","fingerprint":"4dd95641891c9a01","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce tip de instrumentar este indicat pentru includerea în conturul marginal a șanțurilor adiacente cu aspect suspicios, la prepararea cavităților de clasa I modificate?","options":[{"id":"A","text":"Instrumentar de mână pentru tăierea smalțului nesusținut"},{"id":"B","text":"Freze cilindro-conice acționate la turație înaltă"},{"id":"C","text":"Freze de fisurotomie utilizate la turație înaltă"},{"id":"D","text":"Freze sferice de dimensiuni reduse la turație joasă"},{"id":"E","text":"Freze diamantate în formă de flacără la turație convențională"}],"correct":["B","C"],"pages":[69],"source":"set-2"},{"id":"set2-IJA-yWKk","fingerprint":"253a82c5a6b19a92","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile adevărate privind prepararea cavităților de tip „tunel” și „galerie” în tratamentul leziunilor carioase proximale fără acces direct?","options":[{"id":"A","text":"Profunzimea cavității de tip „tunel” este de regulă superficială datorită traiectoriei ocluzo-proximale."},{"id":"B","text":"Cavitatea de tip „tunel” prezintă un risc de deschidere a camerei pulpare sau de fractură a crestei marginale restante prea subțiri."},{"id":"C","text":"Peretele vestibular este absent în cazul „galeriei” de tip slot deschis."},{"id":"D","text":"„Galeria” se realizează exclusiv la molari datorită volumului coronar superior."},{"id":"E","text":"Cavitatea de tip „tunel” este recomandată fără restricții la premolari și molari."}],"correct":["B","C"],"pages":[70],"source":"set-2"},{"id":"set2-nFl59TQR","fingerprint":"dbcd813a157b1942","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce tipuri de cavități se prepară în cazul leziunilor carioase proximale care prezintă subminarea sau întreruperea crestei marginale, în funcție de gradul de distrugere a acesteia?","options":[{"id":"A","text":"Casetă modificată pentru materiale aderente, atunci când există acces direct prin absența dintelui vecin."},{"id":"B","text":"Cavitate de tip „galerie”, cu traiectorie strict ocluzo-proximală și întrerupere completă a ariei de contact."},{"id":"C","text":"Cavitate clasică de clasa a II-a modificată, caracterizată prin întrerupere mare a crestei marginale și profunzime mare."},{"id":"D","text":"Cavitate de tip „slot”, caracterizată prin aspect paralelipipedic cu unghiuri interne rotunjite și întrerupere medie a crestei marginale."},{"id":"E","text":"Cavitate de tip „picătură”, caracterizată prin întrerupere mică a crestei marginale și profunzime medie."}],"correct":["C","D","E"],"pages":[70],"source":"set-2"},{"id":"set2-yLNheJSm","fingerprint":"f28b796918ad558d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt regulile generale privind prepararea locașurilor și aplicarea pinurilor parapulpare ca sisteme suplimentare de retenție?","options":[{"id":"A","text":"Locașurile se realizează în dentina peretelui vestibular, la minim 1 mm de joncțiunea amelo-dentinară."},{"id":"B","text":"Distanța minimă necesară între două pinuri parapulpare aplicate în aceeași cavitate este de 2 mm."},{"id":"C","text":"Locașurile trebuie plasate la minim 1 mm în interiorul joncțiunii amelo-dentinare."},{"id":"D","text":"Prepararea locașurilor se realizează cu freze speciale la turație redusă."},{"id":"E","text":"Pinurile parapulpare se aplică exclusiv prin cimentare cu ionomer de sticlă, pentru a evita tensiunile interne."}],"correct":["B","C","D"],"pages":[71],"source":"set-2"},{"id":"set2-cWnbf0-W","fingerprint":"9a665072ffdf4fb3","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile peretelui gingival în prepararea cavităților de clasa a II-a modificate pentru materiale aderente?","options":[{"id":"A","text":"Dacă peretele gingival este concav, smalțul subminat trebuie îndepărtat complet pentru a preveni fractura prismelor de smalț în timp."},{"id":"B","text":"Marginea de smalț gingival nedemineralizat, chiar dacă este subminată semnificativ, poate fi păstrată pentru a asigura o închidere marginală în smalț."},{"id":"C","text":"Un perete gingival plan, cu smalț susținut în totalitate, realizează un unghi de aproximativ 90 de grade cu restul suprafeței proximale."},{"id":"D","text":"Peretele gingival are întotdeauna o suprafață convexă pentru a oferi rezistență maximă materialului de restaurare."},{"id":"E","text":"Pragul gingival se bizotează obligatoriu pentru a spori adeziunea la marginile cavității."}],"correct":["B","C"],"pages":[70],"source":"set-2"},{"id":"set2-CiC1vqkK","fingerprint":"75e946d82667a084","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt particularitățile deschiderii ocluzale și ale extinderii cavităților în prepararea leziunilor proximale pentru materiale aderente?","options":[{"id":"A","text":"Deschiderea ocluzală a cavităților clasice modificate nu depășește niciodată limitele fosetei proximale."},{"id":"B","text":"Când caria proximală coexistă cu carii ocluzale extinse separate prin punți subțiri de smalț sănătos sub 1 mm, acestea pot fi unite într-o cavitate compusă unică."},{"id":"C","text":"În cazul cavităților de tip „picătură” și „slot”, deschiderea ocluzală este localizată în regiunea crestei marginale și a fosetei proximale."},{"id":"D","text":"Realizarea unei cavități unice proximo-ocluzale scutește practicianul de respectarea regulilor specifice de preparare pentru partea proximală."},{"id":"E","text":"Dacă o obturație veche de amalgam este îndepărtată, extensia ocluzală rezultată se limitează strict la creasta marginală."}],"correct":["B","C"],"pages":[70],"source":"set-2"},{"id":"set2-jqdOAKxJ","fingerprint":"5f07806c680c7e0b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este abordarea de preparare recomandată în cazul cariilor proximale cavitare fără subminarea crestei marginale, atunci când există acces direct la suprafața afectată?","options":[{"id":"A","text":"Se creează un perete gingival puternic concav cu bizotarea obligatorie a pragului gingival."},{"id":"B","text":"Se extinde preparația ocluzal până la depășirea fosetei proximale, pentru a asigura retenția."},{"id":"C","text":"Se prepară o cavitate de tip „tunel” cu traiectorie ocluzo-proximală."},{"id":"D","text":"Se prepară o cavitate de tip „galerie” cu un perete vestibular absent."},{"id":"E","text":"Se realizează o casetă modificată pentru materiale aderente, cu margini de smalț care pot fi bizotate."}],"correct":["E"],"pages":[70],"source":"set-2"},{"id":"set2-5OAteR6e","fingerprint":"1d614c660c62aad8","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt regulile de bază referitoare la accesul și conservarea țesuturilor în prepararea cavităților proximale pe dinții frontali?","options":[{"id":"A","text":"Păstrarea smalțului vestibular nesusținut este permisă pe fondul absenței forțelor directe care se exercită asupra suprafeței vestibulare."},{"id":"B","text":"Accesul se realizează predominant dinspre vestibular, cu excepția cazurilor în care creasta marginală orală este distrusă."},{"id":"C","text":"Smalțul oral nesusținut este menținut alături de cel vestibular, datorită absenței forțelor masticatorii directe în această zonă."},{"id":"D","text":"Accesul se realizează dinspre oral, cu excepția situațiilor în care există modificări de poziție sau înclinație care împiedică acest tip de abord."},{"id":"E","text":"Smalțul vestibular nesusținut trebuie îndepărtat complet pentru a preveni fracturarea ulterioară sub acțiunea directă a forțelor ocluzale."}],"correct":["A","D"],"pages":[71],"source":"set-2"},{"id":"set2-IqT8SSp3","fingerprint":"abcd9b181d999a8f","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Cum se realizează corect prepararea peretelui gingival și bizotarea marginilor în cazul cavităților cu subminarea crestelor la dinții frontali?","options":[{"id":"A","text":"Bizotarea se efectuează atât în smalț cât și în dentina superficială, pentru a asigura o tranziție cromatică optimă și o retenție superioară."},{"id":"B","text":"Marginile cavităților medii sau mari se bizotează vestibular la turație redusă, ținând cont de stopurile ocluzale de gradul al II-lea."},{"id":"C","text":"Se evită bizotarea peretelui gingival cu smalț pentru a preveni distrugerea completă a smalțului subțire necesar închiderii marginale."},{"id":"D","text":"Peretele gingival cu smalț se bizotează obligatoriu pentru a crește retenția și a facilita integrarea estetică a materialelor aderente."},{"id":"E","text":"Bizotarea smalțului oral se realizează exclusiv în scop estetic, cu freze extradure la turație înaltă."}],"correct":["C"],"pages":[72],"source":"set-2"},{"id":"set2-iBcQmtiZ","fingerprint":"0f614bbb5caec7ec","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile reale ale formelor de retenție suplimentară specifice cavităților de clasa a IV-a?","options":[{"id":"A","text":"Șanțurile dentinare reprezintă prima opțiune de retenție, fiind realizate de rutină la intersecția pereților laterali cu cel parapulpar."},{"id":"B","text":"În cazul cavităților cu extindere mare, bizotarea se realizează și oral sau pe tot conturul marginal pentru o retenție suplimentară sporită."},{"id":"C","text":"Știfturile parapulpare metalice utilizate pentru creșterea retenției sunt acoperite cu opacifianți pentru a menține o estetică favorabilă."},{"id":"D","text":"Bizoul oral are o lățime superioară comparativ cu cel vestibular, pentru a asigura o rezistență optimă împotriva forțelor ocluzale directe."},{"id":"E","text":"Lățimea bizoului vestibular trebuie să fie de minim 1,5-2 mm, fiind dictată în mod direct de necesitățile fizionomice."}],"correct":["B","C","E"],"pages":[72],"source":"set-2"},{"id":"set2-_LUbhmFy","fingerprint":"034c82d0cd7b937d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce particularități prezintă cavitățile de clasa a III-a preparate în absența accesului direct, fără subminarea crestelor vestibulare și orale?","options":[{"id":"A","text":"Sunt preparate profund în dentină pentru a oferi o zonă optimă de retenție mecanică în absența unui smalț adecvat."},{"id":"B","text":"Accesul se creează predominant dinspre vestibular pentru a facilita aplicarea instrumentarului mecanic fără a sacrifica structura dentară orală."},{"id":"C","text":"Prezintă o suprafață internă rotunjită și pereți laterali divergenți spre suprafață, rezultați direct din forma frezei sferice utilizate."},{"id":"D","text":"Adoptă frecvent forma unei casete modificate, realizată prin obținerea unui spațiu suficient de acces în urma separării rapide și netraumatice cu pene."},{"id":"E","text":"Peretele oral poate fi conservat parțial sau poate lipsi cu desăvârșire, în funcție de maniera specifică prin care s-a obținut accesul cavitar."}],"correct":["C","E"],"pages":[71],"source":"set-2"},{"id":"set2-r9OldTFp","fingerprint":"da02a0b13cba9c54","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este parametrul clinic distinctiv prin care o cavitate de clasa a III-a este diferențiată de o cavitate de clasa a IV-a modificată pentru materiale aderente, pe dinții frontali?","options":[{"id":"A","text":"Profunzimea preparării peretelui parapulpar raportată la proiecția camerei pulpare și a stopurilor ocluzale de gradul al II-lea."},{"id":"B","text":"Dimensiunea absolută a bizoului vestibular care trebuie să depășească lățimea de 2 mm pentru satisfacerea cerințelor estetice superioare."},{"id":"C","text":"Necesitatea imperioasă a utilizării pinurilor parapulpare metalice pentru a asigura retenția primară a viitoarei restaurări adezive."},{"id":"D","text":"Direcția de evoluție a cariei dentare spre suprafața orală, însoțită de subminarea completă a crestelor marginale de smalț."},{"id":"E","text":"Implicarea sau neimplicarea muchiei incizale ca rezultat al etapei de îndepărtare a țesuturilor dentare care nu mai pot fi conservate."}],"correct":["E"],"pages":[71],"source":"set-2"},{"id":"set2-MtoLloqy","fingerprint":"f77b12d45286b5ce","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile clinico-tehnice ale preparațiilor mici pentru cariile cavitare cervicale de clasa a V-a?","options":[{"id":"A","text":"Prezintă frecvent o extindere subgingivală marcată pentru retenția materialului."},{"id":"B","text":"Peretele axial este întotdeauna perfect nivelat."},{"id":"C","text":"Se realizează frecvent cu instrumentar rotativ sferic la turație convențională."},{"id":"D","text":"Bizotarea suplimentară se practică de elecție pe marginea gingivală."},{"id":"E","text":"Pereții laterali sunt ușor divergenți către exterior."}],"correct":["C","E"],"pages":[72],"source":"set-2"},{"id":"set2-4x-YPeN6","fingerprint":"339a3672b96abf3b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu adecvat geometria și regulile de bizotare pentru preparațiile extinse de clasa a V-a?","options":[{"id":"A","text":"Pentru creșterea retenției în cavitățile foarte mari, se pot realiza șanțuri cu freza sferică mică la turație redusă."},{"id":"B","text":"Marginile preparate în cement se bizotează sistematic pentru creșterea adeziunii."},{"id":"C","text":"Peretele axial are un contur nivelat, fiind ușor convex în plan vertical."},{"id":"D","text":"Pereții laterali realizează unghiuri de 90° cu suprafața dintelui dacă marginea cervicală este situată în cement."},{"id":"E","text":"Lățimea minimă necesară a zonei de smalț bizotate este fixă, fiind standardizată la 2 mm."}],"correct":["A","C","D"],"pages":[73],"source":"set-2"},{"id":"set2-YoD9tH-b","fingerprint":"86ac37a74f8a93f4","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce particularități terapeutice prezintă materialele de obturație specifice și managementul smalțului marginal în cariile de clasa a V-a?","options":[{"id":"A","text":"Preparațiile destinate obturării cu cimenturi cu ionomeri de sticlă necesită bizotare extinsă indiferent de situație."},{"id":"B","text":"Smalțul nesusținut de la nivel cervical, cu grosime adecvată, este frecvent păstrat."},{"id":"C","text":"Cimenturile cu ionomeri de sticlă modificate cu rășini impun bizotarea smalțului marginal."},{"id":"D","text":"Cariile circulare de clasa a V-a reprezintă o evoluție în suprafață spre incizal și ocluzal."},{"id":"E","text":"Evoluția în profunzime a formelor clinice de carii cervicale limitează întotdeauna cavitatea la stadiul superficial."}],"correct":["B"],"pages":[72],"source":"set-2"},{"id":"set2-ABfT-cRJ","fingerprint":"09aca71fec6d8f2c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care caracteristică descrie corect abordarea marginii cervicale situate în cement în cadrul preparațiilor extinse de clasa a V-a?","options":[{"id":"A","text":"Necesită bizotare exclusivă cu instrumentar rotativ sferic la turație convențională."},{"id":"B","text":"Realizează unghiuri de 90° cu suprafața dintelui, nefiind bizotată."},{"id":"C","text":"Prezintă șanțuri retentive realizate cu freza cilindrică direct pe marginea preparată."},{"id":"D","text":"Se bizotează la o lățime de 0,5-1,5 mm pentru a facilita necesitățile fizionomice."},{"id":"E","text":"Se bizotează obligatoriu pentru a crește gradul de retenție globală al preparației."}],"correct":["B"],"pages":[73],"source":"set-2"},{"id":"set2-24AtCoto","fingerprint":"1e596b4477bf4003","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt rolurile și mecanismele de acțiune ale primerului la nivelul dentinei, în funcție de moleculele și solventul din compoziția sa?","options":[{"id":"A","text":"Transformă un țesut hidrofil într-unul hidrofob prin tapetarea tubulilor dentinari deschiși și a spațiilor intercolagenice cu molecule monomerice bifuncționale."},{"id":"B","text":"Un solvent care asociază alcoolul și apa îndeplinește simultan funcția de îndepărtare a apei în exces din dentina umedă și de rehidratare a rețelei de colagen."},{"id":"C","text":"Solventul cu apă rehidratează rețeaua de colagen deshidratată și colabată consecutiv uscării dentinei cu aer."},{"id":"D","text":"Moleculele monomerice bifuncționale au un capăt hidrofob de legare la dentină și un capăt hidrofil de legare la adeziv."},{"id":"E","text":"Solventul care conține apă are rolul principal de a îndepărta apa în exces din dentina umedă obținută prin uscare cu buleta de vată."}],"correct":["A","B","C"],"pages":[73,74,75,76,77],"source":"set-2"},{"id":"set2-nENKxv8B","fingerprint":"181b8cf4cb0823fe","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este caracteristica definitorie a unui sistem adeziv de generația a VI-a în ceea ce privește prezentarea componentelor sale?","options":[{"id":"A","text":"Incorporează nanoumplutură în matricea adezivului pentru creșterea rezistenței mecanice."},{"id":"B","text":"Acidul demineralizant este ambalat separat, în timp ce primerul și adezivul sunt amestecate într-un recipient comun."},{"id":"C","text":"Conține acidul demineralizant, primerul și adezivul în trei recipiente complet separate."},{"id":"D","text":"Acidul demineralizant și primerul sunt amestecate împreună, iar adezivul este furnizat într-un recipient separat."},{"id":"E","text":"Toate cele trei componente (acid, primer, adeziv) se află concentrate într-un singur recipient."}],"correct":["D"],"pages":[73,74,75,76,77],"source":"set-2"},{"id":"set2-7MlWdSTF","fingerprint":"207ca57d0a4a380c","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile clinice și fizico-chimice ale materialelor biologic active utilizate pentru protecția pulpo-dentinară?","options":[{"id":"A","text":"Variantele fotopolimerizabile ale materialelor biologic active prezintă o capacitate foarte bună de sigilare a plăgii dentinare datorită componentei lor rășinice."},{"id":"B","text":"Materialele autopolimerizabile pe bază de silicați de calciu se aplică exclusiv în strat subțire (0,2-1 mm) și se dizolvă cu ușurință sub acțiunea fluidului dentinar."},{"id":"C","text":"Variantele fotopolimerizabile generează efecte biologice mult superioare variantelor autopolimerizabile corespondente."},{"id":"D","text":"Materialele autopolimerizabile pe bază de silicați de calciu au costuri crescute și timp de priză prelungit, dar oferă efecte biologice comparabile sau mai bune față de cele cu hidroxid de calciu."},{"id":"E","text":"Materialele autopolimerizabile pe bază de hidroxid de calciu au rezistență mecanică scăzută, se dizolvă ușor și prezintă o capacitate redusă de sigilare a plăgii dentinare."}],"correct":["A","D","E"],"pages":[73,74,75,76,77],"source":"set-2"},{"id":"set2-F4UgaoRd","fingerprint":"eeda08f98817a415","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce trăsături definesc linerii și bazele utilizate în tratamentul cariei simple cavitare?","options":[{"id":"A","text":"Bazele sunt straturi protectoare care depășesc 1 mm în grosime și se remarcă printr-o rezistență mecanică superioară."},{"id":"B","text":"Clasele de lineri pot fi reprezentate de sigilanți dentinari, materiale în suspensie, cimenturi sau materiale modificate cu rășini."},{"id":"C","text":"Linerii se aplică în straturi cuprinse între 0,2 și 1 mm și asigură protecție pasivă, anumiți produși având suplimentar un efect activ (sedativ, antiinflamator sau antimicrobian)."},{"id":"D","text":"Linerii în suspensie generează rapid un strat rigid de 20-30 de microni imediat după evaporarea solventului."},{"id":"E","text":"Cimentul fosfat de zinc (FOZ) este utilizat ca bază de primă intenție în cavitățile profunde, deoarece stimulează acțiunea biologică a produșilor pe bază de calciu."}],"correct":["A","B","C"],"pages":[73,74,75,76,77],"source":"set-2"},{"id":"set2-2fOaar4h","fingerprint":"360b41c5667750ec","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este protocolul de lucru și mecanismul de acțiune pentru aplicarea acidului ortofosforic în cadrul procedurii de gravaj acid total pentru un sistem de generația a IV-a?","options":[{"id":"A","text":"La nivelul dentinei se recomandă un timp de acțiune de maxim 10-15 secunde pentru îndepărtarea detritusului dentinar remanent și dezvelirea fibrelor de colagen."},{"id":"B","text":"Se aplică pe smalț exclusiv timp de 30-45 de secunde pentru a garanta crearea unor retenții macromecanice."},{"id":"C","text":"Procesul de demineralizare la nivelul dentinei consolidează dopurile de detritus dentinar remanent (smear plugs) intratubulare."},{"id":"D","text":"La nivelul smalțului, aplicarea acidului determină îndepărtarea smear layer-ului și expunerea tubulilor inter și peritubulari."},{"id":"E","text":"Acidul se aplică mai întâi pe dentină timp de 15 secunde, urmat de smalț pentru încă 15 secunde, în scopul prevenirii sensibilității postoperatorii."}],"correct":["A"],"pages":[73,74,75,76,77],"source":"set-2"},{"id":"set2-G3xo6UcA","fingerprint":"b486103ad218af44","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile corecte referitoare la rolul și acțiunea primerului la nivelul structurilor dentare?","options":[{"id":"A","text":"Conține molecule bifuncționale cu un capăt hidrofil de legare la adeziv și un capăt hidrofob de legare la dentină."},{"id":"B","text":"Dacă smalțul este umed, determină îndepărtarea umidității remanente după etapa de spălare a acidului."},{"id":"C","text":"Transformă dentina dintr-un țesut hidrofob într-unul hidrofil, tapetând tubulii dentinari."},{"id":"D","text":"Solventul pe bază de apă rehidratează rețeaua de colagen deshidratată și colabată în urma uscării cu aer."},{"id":"E","text":"La nivelul smalțului uscat, prezența primerului nu influențează legarea adezivului de zonele gravate."}],"correct":["B","D","E"],"pages":[76],"source":"set-2"},{"id":"set2-3MrNCg1I","fingerprint":"3263e0a46048983d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele caracteristici sunt proprii sistemelor adezive de generațiile IV și V?","options":[{"id":"A","text":"Aplicarea restaurărilor polimerice de durată necesită obligatoriu un timp separat de demineralizare la nivelul smalțului."},{"id":"B","text":"Este recomandată obținerea unei dentine uscate cu ajutorul unui jet de aer pentru realizarea unui strat hibrid corespunzător."},{"id":"C","text":"Sunt sisteme de tip „etch and rinse-off”, aplicarea acidului demineralizant nefiind urmată de spălare."},{"id":"D","text":"Realizează un gravaj acid total, acidul fiind aplicat succesiv și la timpi diferiți pe smalț și dentină."},{"id":"E","text":"Primerul utilizat în compoziția acestor sisteme este formulat, în mod frecvent, pe bază de alcool."}],"correct":["A","D","E"],"pages":[76],"source":"set-2"},{"id":"set2-lyC0ydWL","fingerprint":"6c0a6c160adb4500","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Ce afirmație referitoare la stratul de adeziv aplicat la nivelul cavității este corectă?","options":[{"id":"A","text":"Straturile aplicate prin pensulare pe smalț și pe dentină sunt polimerizate timp de 15-20 de secunde."},{"id":"B","text":"Pentru a favoriza absorbția tensiunilor induse de contracția de polimerizare, stratul superficial de adeziv trebuie să fie cât mai subțire."},{"id":"C","text":"Aplicarea adezivului se realizează exclusiv la nivelul dentinei, unde pătrunde în tubulii deschiși."},{"id":"D","text":"Stratul hibrid reprezintă o structură formată exclusiv prin interacțiunea monomerilor adezivi cu smalțul demineralizat."},{"id":"E","text":"Succesul aplicării clinice se verifică vizual prin identificarea unui strat de adeziv uniform și complet mat."}],"correct":["A"],"pages":[76],"source":"set-2"},{"id":"set2-4uFlLq6m","fingerprint":"75bc7468f17bb1ad","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt particularitățile tehnice ale sistemelor adezive de generațiile VI și VII?","options":[{"id":"A","text":"Primerul din structura acestor sisteme este, în mod frecvent, formulat pe bază de apă."},{"id":"B","text":"Nu pot fi utilizate pentru aplicarea straturilor interne destinate înlocuirii masei dentinare."},{"id":"C","text":"Necesită aplicarea stratului de acid demineralizant urmată obligatoriu de o etapă de spălare."},{"id":"D","text":"Necesită un timp suplimentar de 15-20 secunde pentru demineralizarea separată a smalțului."},{"id":"E","text":"Optimizarea stratului hibrid se obține prin aplicarea lor pe o dentină uscată cu ajutorul jetului de aer."}],"correct":["A","D","E"],"pages":[76],"source":"set-2"},{"id":"set2-oQkxUEt_","fingerprint":"56eee5ba2005bbc6","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect variantele de tratament ale unei cavități medii?","options":[{"id":"A","text":"În varianta clasică, aplicarea unui liner pasiv sau a unei baze se stabilește în funcție de distanța până la joncțiunea amelo-dentinară."},{"id":"B","text":"Sistemul adeziv se aplică pe stratul de sigilare și protecție doar dacă acesta este compus exclusiv din hidroxid de calciu pur."},{"id":"C","text":"Varianta modernă se caracterizează prin renunțarea la utilizarea linerilor sau a bazei, aplicându-se direct sistemul adeziv."},{"id":"D","text":"În varianta clasică, sistemul adeziv se aplică atât pe structurile dure, cât și pe materialele pe bază de silicați de calciu."},{"id":"E","text":"Varianta modernă impune aplicarea sistemului adeziv doar după ce a fost utilizat în prealabil un ciment ionomer de sticlă."}],"correct":["A","C","D"],"pages":[76],"source":"set-2"},{"id":"set2-dcU219Oi","fingerprint":"1809125ce29c172d","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile adevărate privind varianta modernă a coafajului indirect într-o cavitate profundă care prezintă dentină dură normală sau afectată la nivel pulpar/parapulpar?","options":[{"id":"A","text":"Pentru dentina cu grosime cuprinsă între 0,5 mm și 2 mm, protocolul impune aplicarea obligatorie a unui liner activ sub stratul de protecție rezistent mecanic."},{"id":"B","text":"Grosimea totală a straturilor de liner activ, liner rezistent mecanic și dentină remanentă trebuie să însumeze 2 mm, atunci când dentina restantă este sub 0,5 mm."},{"id":"C","text":"Dacă stratul de dentină restant este mai mic de 0,5 mm, se aplică exclusiv un liner activ sub materialul de restaurare."},{"id":"D","text":"Sistemul adeziv este contraindicat a fi aplicat peste stratul de protecție format din materiale pe bază de silicați de calciu."},{"id":"E","text":"Dacă stratul de dentină restant este cuprins între 0,5 mm și 2 mm, se indică aplicarea unui liner rezistent mecanic."}],"correct":["B","E"],"pages":[77,78],"source":"set-2"},{"id":"set2-T1zCQOMh","fingerprint":"66398334c203f396","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt condițiile necesare care trebuie îndeplinite simultan pentru realizarea tehnicilor de tratament cu păstrarea limitată a dentinei necrotice (tehnica „stepwise” și tehnica „selectivă de îndepărtare”)?","options":[{"id":"A","text":"Prezența semnelor radiologice incipiente de lărgire a spațiului parodontal în istoricul dintelui."},{"id":"B","text":"Absența oricărui semn de patologie pulpară sau periapicală evidențiabil clinic și radiologic la momentul tratamentului."},{"id":"C","text":"Păstrarea dentinei necrotice pe zone limitate este justificată de riscul deschiderii camerei pulpare în cazul îndepărtării complete."},{"id":"D","text":"Dinte cu sensibilitate confirmată."},{"id":"E","text":"Posibilitatea finalizării tratamentului conservator exclusiv într-o singură ședință clinică."}],"correct":["B","C","D"],"pages":[77,78],"source":"set-2"},{"id":"set2-vvH-LIA3","fingerprint":"f1fb4e79fe63f1b8","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În cadrul primei ședințe de tratament (comună atât tehnicii „stepwise” cât și celei „selective”), protocolul clinic într-o cavitate profundă presupune:","options":[{"id":"A","text":"Îndepărtarea completă a dentinei necrotice de pe peretele juxtapulpar pentru a obține o curățare mecanică exhaustivă."},{"id":"B","text":"Realizarea toaletei și a dezinfectării cavității brute, în funcție de situația clinică."},{"id":"C","text":"Aplicarea unei obturații coronare intermediare exclusiv din rășini compozite fotopolimerizabile direct peste stratul neodentinogenetic."},{"id":"D","text":"Păstrarea unui strat circumferențial de dentină dură pe o distanță de 1-1,5 mm până la joncțiunea amelo-dentinară."},{"id":"E","text":"Utilizarea unui material de restaurare intermediară care să aibă proprietăți ce asigură o închidere marginală foarte bună și sigilare dentinară eficientă."}],"correct":["B","D","E"],"pages":[77,78],"source":"set-2"},{"id":"set2-PYDqXgQ5","fingerprint":"628aa32e4b202675","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Referitor la atitudinea terapeutică abordată în cea de-a doua ședință (efectuată după 6-9 luni), ce afirmații sunt valabile în funcție de tehnica aleasă și de prezența sau absența semnelor patologice?","options":[{"id":"A","text":"În tehnica „stepwise”, după excavarea stratului necrotic rezidual, nu mai este necesară aplicarea unui nou strat neodentinogenetic."},{"id":"B","text":"Prezența semnelor patologice clinice sau radiologice la control dictează continuarea tratamentului prin repetarea excavației și sigilării dentinare cu CIMR."},{"id":"C","text":"În tehnica „selectivă” (absența semnelor patologice), se îndepărtează obligatoriu toate straturile de protecție pulpară pentru aplicarea materialului de restaurare de durată."},{"id":"D","text":"În tehnica „stepwise” (absența semnelor patologice), se îndepărtează toate materialele aplicate inițial și parțial din dentina necrotică reziduală."},{"id":"E","text":"În tehnica „selectivă”, a doua ședință nu mai are loc dacă cimentul ionomer aplicat în prima ședință prezintă caracteristici adecvate de refacere de durată."}],"correct":["D","E"],"pages":[77,78],"source":"set-2"},{"id":"set2-Uqll_B7b","fingerprint":"fe7cc81e6909e907","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este atitudinea terapeutică impusă de varianta modernă a coafajului indirect realizat într-o cavitate profundă cu dentină dură, atunci când stratul de dentină restantă este mai mic de 0,5 mm?","options":[{"id":"A","text":"Tratamentul se temporizează, materialul de restaurare de durată aplicându-se după minimum 6-9 luni pentru a asigura neodentinogeneza."},{"id":"B","text":"Se aplică un liner activ și un liner rezistent mecanic, ajustând grosimea astfel încât suma straturilor de linere și a dentinei remanente să atingă 2 mm."},{"id":"C","text":"Se indică păstrarea unui strat de dentină necrotică pentru a se obține artificial o grosime totală de 2 mm."},{"id":"D","text":"Se utilizează exclusiv un liner rezistent mecanic de tip CIMR, urmat imediat de aplicarea sistemului adeziv."},{"id":"E","text":"Se aplică doar un liner activ într-un strat considerabil, compensând asfel lipsa dentinei prin acțiunea remineralizantă."}],"correct":["B"],"pages":[77,78],"source":"set-2"},{"id":"set2-aeuWiHX_","fingerprint":"b67b7512f6e130d8","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații referitoare la tehnicile stratificate de aplicare a materialelor compozite vâscoase sunt adevărate?","options":[{"id":"A","text":"Avantajul principal constă în accelerarea timpului de lucru prin reducerea numărului de straturi."},{"id":"B","text":"Un dezavantaj major este reprezentat de posibila apariție a golurilor între straturi și de contaminarea acestora."},{"id":"C","text":"Tehnica presupune aplicarea de straturi cu o grosime maximă de 2 mm."},{"id":"D","text":"O regulă esențială pentru reducerea factorului C este unirea a cel puțin doi pereți opuși printr-un singur strat."},{"id":"E","text":"Tehnicile permit reducerea contracției de polimerizare și realizarea unor restaurări estetice."}],"correct":["B","C","E"],"pages":[78],"source":"set-2"},{"id":"set2-O1tSEYR8","fingerprint":"c1ac1a890803aa0e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele afirmații descrie corect tehnica „injection molded” utilizată în restaurarea cavităților proximale pe dinții laterali?","options":[{"id":"A","text":"Tehnica presupune utilizarea exclusivă a unei bile de compozit prepolimerizat aplicată la nivelul ariei de contact."},{"id":"B","text":"Un strat de compozit fluid de 0,5 mm se aplică peste adezivul fotopolimerizat, iar excesul de fluid este îndepărtat anterior fotopolimerizării stratului compozit."},{"id":"C","text":"Adezivul se fotopolimerizează separat, urmat de aplicarea și fotopolimerizarea simultană a compozitului fluid și compozitului pastă."},{"id":"D","text":"Adezivul, compozitul fluid și compozitul pastă sunt aplicate succesiv și fotopolimerizate simultan, la finalul aplicării compozitului pastă."},{"id":"E","text":"Presupune aplicarea unui strat subțire de material pastă pe matricea metalică, fotopolimerizat inițial pentru a transforma cavitatea din clasa a II-a în clasa I."}],"correct":["D"],"pages":[79],"source":"set-2"},{"id":"set2-H7hCNHxO","fingerprint":"607b2c15fba65b05","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la tehnicile de restaurare a cavităților din șanțuri și fosete?","options":[{"id":"A","text":"Tehnica de restaurare cu index ocluzal este indicată pentru suprafețele cu șanțuri și fosete întrerupte puțin de procesul carios."},{"id":"B","text":"În tehnica de refacere anatomic-stratificată, cuspizii pot fi refăcuți complet, pe rând, aplicând inițial masa de dentină și ulterior cea de smalț, cu fotopolimerizare succesivă."},{"id":"C","text":"Tehnica de restaurare cu index ocluzal necesită amprentarea inițială a suprafeței ocluzale."},{"id":"D","text":"Tehnica de refacere cu straturi orizontale reprezintă varianta cea mai favorabilă pentru reducerea factorului C."},{"id":"E","text":"Tehnica de refacere anatomic-stratificată presupune refacerea simultană a tuturor cuspizilor exclusiv din masa de smalț."}],"correct":["A","B","C"],"pages":[78],"source":"set-2"},{"id":"set2-TyBETl_E","fingerprint":"423cd4b002f2e33b","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Referitor la tehnicile de restaurare a cavităților proximale de pe dinții laterali, sunt adevărate următoarele afirmații:","options":[{"id":"A","text":"Tehnica de refacere anatomică a peretelui proximal presupune aplicarea succesivă de straturi orizontale de material fluid."},{"id":"B","text":"Tehnica de refacere anatomică a peretelui proximal utilizează un instrument de mână pentru conformarea ariei de contact."},{"id":"C","text":"În tehnica „snow plow”, compozitul pastă este aplicat peste un strat de compozit fluid nepolimerizat."},{"id":"D","text":"Tehnica de refacere centripetă transformă o cavitate de clasa a II-a într-una de clasa I prin refacerea inițială a porțiunii proximale pe o matrice metalică."},{"id":"E","text":"Tehnica de refacere centripetă utilizează exclusiv pene din materiale transparente."}],"correct":["B","C","D"],"pages":[79],"source":"set-2"},{"id":"set2-4hp3jL1S","fingerprint":"96486830a5c7cf53","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnicile de aplicare a materialelor fluide (flow)?","options":[{"id":"A","text":"Apariția golurilor în tehnica fără contact poate fi prevenită prin omogenizarea materialului folosind un fuloar cilindric."},{"id":"B","text":"În tehnica prin contact tangențial, vârful seringii trebuie să se afle la distanță de peretele dentar pentru a asigura omogenizarea."},{"id":"C","text":"Tehnica fără contact are avantajul principal de a elimina complet riscul apariției golurilor de aer."},{"id":"D","text":"Tehnica prin contact tangențial implică poziționarea oblică a vârfului seringii în contact cu peretele dentar."},{"id":"E","text":"Aplicarea materialelor fluide prin contact tangențial previne formarea de bule de aer la aplicarea stratificată sau în masă."}],"correct":["A","D","E"],"pages":[79],"source":"set-2"},{"id":"set2-j07o-7Kw","fingerprint":"e513684d9c1e09b1","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următorii factori favorizează obținerea unei închideri marginale corecte în cazul restaurărilor cu materiale compozite?","options":[{"id":"A","text":"Creșterea fluidității materialelor compozite vâscoase prin intermediul metodelor de încălzire sau sonice."},{"id":"B","text":"Utilizarea unui sistem adeziv autogravant aparținând generației a VII-a."},{"id":"C","text":"Existența unor margini de smalț sănătos și susținut dentinar, lipsite de anfractuozități."},{"id":"D","text":"Realizarea unui bizou la nivelul marginilor supuse forțelor mecanice directe."},{"id":"E","text":"Utilizarea tehnicii anatomice stratificate, cu aplicarea unui strat orizontal între doi pereți opuși."}],"correct":["A","C"],"pages":[79],"source":"set-2"},{"id":"set2-DkAgPneL","fingerprint":"4bbd3b847b16c0b8","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnicile de tip „sandwich” în restaurările dentare?","options":[{"id":"A","text":"Tehnica „sandwich deschis” necesită exclusiv utilizarea compozitelor condensabile aplicate în strat unic."},{"id":"B","text":"În tehnica „sandwich deschis”, baza sau linerul este acoperită doar parțial de materialul de durată aderent."},{"id":"C","text":"Restaurarea „sandwich închis” este indicată specific pentru obturarea cavităților cu evoluție subgingivală."},{"id":"D","text":"Restaurarea „sandwich închis” implică acoperirea în totalitate a linerului sau a bazei de către materialul compozit de durată."},{"id":"E","text":"În ambele variante ale tehnicii „sandwich”, se recomandă aplicarea materialului compozit sub forma unui strat orizontal între doi pereți opuși."}],"correct":["B","D"],"pages":[80],"source":"set-2"},{"id":"set2-9QFFxX2j","fingerprint":"25bd3d8c73806055","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile specifice ale materialelor compozite și ale tehnicilor de aplicare ale acestora?","options":[{"id":"A","text":"Compozitele de tip „bulk-fill base” prezintă o fluiditate redusă și sunt destinate exclusiv înlocuirii smalțului pierdut."},{"id":"B","text":"Tehnica materialelor condensabile previne apariția golurilor, având un proces de condensare asemănător restaurărilor cu amalgam de argint."},{"id":"C","text":"Compozitele de tip „bulk fill body” au o fluiditate în general mai scăzută și sunt utilizate pentru înlocuirea atât a dentinei, cât și a smalțului pierdut."},{"id":"D","text":"Tehnica în masă („bulk”) necesită aplicarea materialului în straturi succesive cu o grosime maximă de 1 milimetru."},{"id":"E","text":"Materialele condensabile au o structură chimică identică cu cea a compozitelor fluide, diferențierea fiind făcută strict de pensulele de aplicare."}],"correct":["B","C"],"pages":[79],"source":"set-2"},{"id":"set2-0WmcDhaK","fingerprint":"8cb547575bff2a22","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect particularitățile restaurării cavităților de clasa I de dimensiuni medii și mari?","options":[{"id":"A","text":"Pentru obținerea rezistenței mecanice necesare se indică utilizarea preponderentă a materialelor de tip pastă."},{"id":"B","text":"Modelarea stratului superficial cu instrumente rotative trebuie efectuată strict înainte de priza materialului de restaurare."},{"id":"C","text":"Aplicarea anatomică stratificată impune introducerea materialelor de restaurare de durată în straturi cu grosimea de maximum 2 mm."},{"id":"D","text":"Variantele fluide ale materialelor de restaurare sunt utilizate cu predilecție pentru aceste cavități datorită adaptării marginale superioare."},{"id":"E","text":"Tehnica de aplicare în masă („bulk”) necesită utilizarea exclusivă a compomerilor fluizi și a polisticlelor."}],"correct":["A","C"],"pages":[80],"source":"set-2"},{"id":"set2-imMTYoRR","fingerprint":"7688576b4cded702","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile reale ale sistemelor matriceale utilizate pentru restaurările proximale în zona laterală?","options":[{"id":"A","text":"Matricele circulare aplicate pe cavități proximale situate pe o singură față necesită o deschidere fenestrată la nivelul feței proximale indemne."},{"id":"B","text":"Depășirea pragului gingival în sens apical de către matrice trebuie să aibă o valoare fixă de 2 mm pentru asigurarea etanșeității."},{"id":"C","text":"Matricele din material plastic prezintă avantajul unor grosimi foarte reduse, facilitând pătrunderea în spațiul interdentar stâmt."},{"id":"D","text":"Matricele din plastic se remarcă printr-o inserție interdentară deosebit de simplă comparativ cu variantele metalice care sunt rigide."},{"id":"E","text":"Matricele metalice facilitează fotopolimerizarea materialelor de restaurare, acționând ca niște oglinzi care reflectă lumina."}],"correct":["A","E"],"pages":[81],"source":"set-2"},{"id":"set2-G95ddr3I","fingerprint":"3a2a17493e8079d9","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce detalii definesc corect tehnicile specifice de aplicare a penelor dentare în procesul de restaurare a cariilor proximale din zona laterală?","options":[{"id":"A","text":"Tehnica „double wedging” este indicată la deschideri mari și constă în inserarea a două pene complet suprapuse la nivelul ariei de contact."},{"id":"B","text":"Distanța suplimentară creată între fețele proximale prin procesul de preseparare trebuie să fie echivalentă cu grosimea matricei selectate."},{"id":"C","text":"În cazul unei evazări minore a pereților verticali se impune inserția strictă a două pene masive pentru a preveni refularea compozitului."},{"id":"D","text":"Tehnica „wedge wedging” se adresează suprafețelor cervicale accentuat concave și utilizează obligatoriu o pană curbă și una flexibilă."},{"id":"E","text":"Tehnica „piggyback wedging” folosește două pene rotunde de diametre variate, pana de dimensiuni mai mici fiind poziționată superior."}],"correct":["B","E"],"pages":[81],"source":"set-2"},{"id":"set2-aAd9hEZm","fingerprint":"3031575e069d8536","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este succesiunea și instrumentarul adecvat pentru modelarea stratului superficial al materialelor de restaurare în cavitățile ocluzale de clasa I?","options":[{"id":"A","text":"Folosirea instrumentelor de mână pentru modelare este oportună doar în faza de duritate maximă, după priza completă a rășinii."},{"id":"B","text":"Tehnica aplicării conformatorului ocluzal (stamp technique) este strict evitată atunci când se introduc materiale prin tehnica în masă („bulk”)."},{"id":"C","text":"Utilizarea exclusivă a instrumentarului rotativ înainte de instalarea prizei materialului asigură conturarea riguroasă a reliefului funcțional."},{"id":"D","text":"Modelarea morfologiei superficiale include acțiunea instrumentelor de mână sau a conformatoarelor înaintea prizei, completată cu prelucrarea rotativă după priză."},{"id":"E","text":"Aplicarea acestui algoritm de modelare ocluzală se restrânge obligatoriu doar la manevrarea materialelor având o vâscozitate redusă."}],"correct":["D"],"pages":[80],"source":"set-2"},{"id":"set2-8lSmFEpv","fingerprint":"770c73e31256b6c4","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Identificați afirmația pertinentă cu referire la integrarea clinică a sistemelor de conformare și a instrumentarului adiacent în restaurarea cavităților de clasa a II-a:","options":[{"id":"A","text":"Un sistem matriceal funcțional aplicat pe pereții dinților posteriori trebuie să se plaseze la maximum 0,5 mm sub pragul gingival."},{"id":"B","text":"Prolongarea unei matrice metalice dincolo de conturul crestei marginale a dintelui adiacent periclitează restaurarea și trebuie evitată."},{"id":"C","text":"Benzile de celuloid reprezintă sistemul matriceal esențial pentru refacerea ariilor de contact la molarii și premolarii cu multiple prelungiri subgingivale."},{"id":"D","text":"Benzile de celuloid pot substitui matricele metalice în zona laterală dacă respectivele cavități nu prezintă deschidere ocluzală."},{"id":"E","text":"Matricele parțiale sunt selectate de rutină în exclusivitate pentru cavitățile cu distrugere masivă la nivelul ambelor muchii proximale."}],"correct":["D"],"pages":[81],"source":"set-2"},{"id":"set2-NtRUGhDj","fingerprint":"838c2610c250d78e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele tipuri de cavități permite, în mod exclusiv, modelarea stratului superficial ocluzal cu ajutorul tehnicilor cu conformator ocluzal individualizat („stamp technique”) dintre variantele de cavități fără deschidere ocluzală?","options":[{"id":"A","text":"Cavitatea de tip „casetă”"},{"id":"B","text":"Cavitatea de tip „picătură”"},{"id":"C","text":"Cavitatea de tip „galerie”"},{"id":"D","text":"Cavitatea de tip „tunel”"},{"id":"E","text":"Cavitatea de tip „slot”"}],"correct":["D"],"pages":[81],"source":"set-2"},{"id":"set2-s-umX8zK","fingerprint":"8b45a896d2e444de","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"La aplicarea anatomic stratificată a materialului de restaurare de durată în componenta proximală a unei cavități, care dintre următoarele reguli procedurale trebuie respectate?","options":[{"id":"A","text":"Materialul se va aplica obligatoriu în secțiune triunghiulară sau trapezoidală."},{"id":"B","text":"Straturile de material aplicate trebuie să nu unească pereții opuși ai cavității."},{"id":"C","text":"Materialul trebuie aplicat exclusiv în secțiune circulară pentru a minimiza stresul de contracție."},{"id":"D","text":"Primul strat de material la nivelul peretelui gingival are o dispunere gingivo-orală, urmat de o dispunere gingivo-vestibulară."},{"id":"E","text":"Ultimul strat proximal urmărește configurarea corespunzătoare, evitându-se supraconturarea crestei marginale."}],"correct":["A","B","E"],"pages":[82],"source":"set-2"},{"id":"set2-V0fdNMcz","fingerprint":"f7745c12d29e949e","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"În situația coexistenței pe același dinte a cariilor cavitare pe ambele fețe proximale și la nivel ocluzal, ce principii guvernează atitudinea terapeutică de unire sau separare a cavităților?","options":[{"id":"A","text":"Dacă există carii ocluzale cu orificii mari de deschidere, cavitățile se vor uni dacă punțile de structură dură sănătoasă sunt mai subțiri de 1 mm."},{"id":"B","text":"Dacă există carii ocluzale cu orificiu mic de deschidere, cavitățile nu se vor uni dacă punțile de structură dură sănătoasă sunt mai groase de 1-1,5 mm."},{"id":"C","text":"Indiferent de mărimea orificiului de deschidere ocluzală, prezența unei punți de smalț sub 2 mm impune unirea obligatorie a cavităților."},{"id":"D","text":"Prepararea cavităților se va efectua strict simultan pe ambele fețe, pentru a asigura o cavitate compusă continuă."},{"id":"E","text":"Rezultatul unirii cavităților proximale și a celor ocluzale cu orificii mari este formarea unei cavități compuse mezio-ocluzo-distale."}],"correct":["A","B","E"],"pages":[82],"source":"set-2"},{"id":"set2-wW_t7j6F","fingerprint":"5041fde9cc466042","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"În abordarea restaurativă a leziunilor cavitare, care este materialul de elecție indicat pentru porțiunea subgingivală, independent de tehnica utilizată pentru restaurarea porțiunii supragingivale?","options":[{"id":"A","text":"Cimenturile ionomere de sticlă (CIS) armate autopolimerizabile."},{"id":"B","text":"Rășinile compozite de tip „bulk” aplicate în strat unic cu grosime de peste 2 mm."},{"id":"C","text":"Rășinile compozite clasice cu aplicare anatomic stratificată."},{"id":"D","text":"Cimenturile ionomere de sticlă modificate cu rășină (CIMR) aplicate în straturi de grosime variabilă."},{"id":"E","text":"Ormocerii aplicați în straturi cu o grosime de maxim 2 mm."}],"correct":["D"],"pages":[82],"source":"set-2"},{"id":"set2-oCy9t0oz","fingerprint":"e5ad5900880e1634","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"La restaurarea unui dinte ce prezintă leziuni carioase pe ambele fețe proximale, în cazul optării pentru utilizarea unei matrice circulare, care este procedura corectă privind „tehnica de alternare a penelor”?","options":[{"id":"A","text":"Penele interdentare se introduc abia la finalul reconstituirii parțiale a ambelor fețe proximale, înainte de polimerizarea stratului ocluzal."},{"id":"B","text":"Se folosește o singură pană interdentară care este mobilizată continuu de pe fața vestibulară spre cea orală pe parcursul aplicării straturilor de material."},{"id":"C","text":"Penele se introduc simultan în ambele nișe gingivale la debutul etapei ortopedice pentru a asigura o distanțare optimă bidirecțională."},{"id":"D","text":"Prima pană se introduce în nișa vecină primei suprafețe de restaurat, se îndepărtează după refacere, iar apoi se introduce o nouă pană în cealaltă nișă gingivală."},{"id":"E","text":"Aplicarea penei se face exclusiv la nivelul feței distale, în timp ce fața mezială este conformată exclusiv prin presiunea matricei."}],"correct":["D"],"pages":[82],"source":"set-2"},{"id":"set2-QeBY9pw0","fingerprint":"a582cf828d81aedf","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect penele utilizate pentru restaurarea cariilor proximale frontale?","options":[{"id":"A","text":"Sunt frecvent transparente și se prezintă într-o gamă foarte variată de modele."},{"id":"B","text":"Se manipulează fără interferențe cu banda de celuloid, care se aplică strict la finalul procedurii."},{"id":"C","text":"Se aplică frecvent dinspre vestibular datorită accesului și vizibilității crescute la acest nivel."},{"id":"D","text":"Se aplică frecvent dinspre oral pentru a compensa vizibilitatea limitată a câmpului operator."},{"id":"E","text":"Aplicarea lor frecventă dinspre vestibular este facilitată și de manipularea permanentă a benzii de celuloid."}],"correct":["A","C","E"],"pages":[83],"source":"set-2"},{"id":"set2-9sK_wKxy","fingerprint":"bacfa3c70d9d3830","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce tipuri de matrice și tehnici de modelare sunt indicate pentru restaurarea cavităților de clasa a III-a și a IV-a?","options":[{"id":"A","text":"Matricele metalice cu design special pentru dinți laterali pot fi utilizate în mod neconvențional pe dinți frontali."},{"id":"B","text":"Modelarea stratului superficial se realizează cu instrumente rotative înainte de inițierea prizei materialului."},{"id":"C","text":"Capele și hemicapele reprezintă exemple de matrice standardizate pentru zona frontală."},{"id":"D","text":"Matricele individualizate pentru zona frontală pot fi realizate prin tehnica mock-up sau wax-up."},{"id":"E","text":"Modelarea stratului superficial de material se realizează cu instrumente de mână exclusiv după priza acestuia."}],"correct":["A","C","D"],"pages":[83],"source":"set-2"},{"id":"set2-Xwg0_Rdi","fingerprint":"5711accea50a17a3","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt particularitățile materialelor și tehnicilor de aplicare stratificată sau în masă („bulk”) la nivelul cavităților frontale?","options":[{"id":"A","text":"Aplicarea în masă este utilizată preponderent pentru cavități mici, ce pot fi obturate cu o singură masă aplicată în straturi de maximum 2 mm."},{"id":"B","text":"Rășinile compozite clasice, ceromerii, ormocerii, compomerii și giomerii reprezintă indicații pentru aplicarea stratificată."},{"id":"C","text":"Pentru aplicarea stratificată, materialele de restaurare necesită o fizionomie foarte bună și o rezistență mecanică medie sau mare."},{"id":"D","text":"Evoluția subgingivală a cavității impune realizarea restaurării de durată la acest nivel cu ciment ionomer de sticlă modificat cu rășină (CIMR)."},{"id":"E","text":"Compozitele „bulk” satisfac exigențe fizionomice superioare, fiind recomandate pentru restaurări cu vizibilitate crescută."}],"correct":["A","B","C","D"],"pages":[83],"source":"set-2"},{"id":"set2-UkuEHFVt","fingerprint":"0236b5c07938b3b3","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este materialul de elecție pentru realizarea restaurării de durată la nivel subgingival, în cazul cavităților de clasa a III-a și a IV-a?","options":[{"id":"A","text":"Cimentul ionomer de sticlă modificat cu rășină (CIMR)"},{"id":"B","text":"Rășinile compozite „low-shrink”"},{"id":"C","text":"Giomerii în varianta fluidă"},{"id":"D","text":"Rășinile compozite de tip „bulk”"},{"id":"E","text":"Ceromerii cu vâscozitate ridicată"}],"correct":["A"],"pages":[83],"source":"set-2"},{"id":"set2-K7wLd0Ud","fingerprint":"a898f38a68d027fe","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele reprezintă criterii principale de selecție a materialelor de durată pentru restaurarea cavităților de clasa a V-a?","options":[{"id":"A","text":"Fizionomie crescută atunci când tratamentul este realizat la nivelul dinților frontali."},{"id":"B","text":"Elasticitate minimă, pentru a preveni deformarea restaurării în zona cervicală."},{"id":"C","text":"Elasticitate crescută, asigurată în general de materialele cu fluiditate crescută."},{"id":"D","text":"Rezistență mecanică crescută la forțele directe, datorită solicitărilor intense din această regiune."},{"id":"E","text":"Lipsa necesității unei rezistențe mecanice crescute la acțiunea forțelor mecanice directe, deoarece nu există astfel de forțe în această regiune."}],"correct":["A","C","E"],"pages":[83],"source":"set-2"},{"id":"set2-vUAmMWCj","fingerprint":"55ac44bee1a52ec9","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile adevărate cu privire la alegerea materialelor în funcție de zona dentară pentru tehnica de aplicare stratificată în cavitățile de clasa a V-a?","options":[{"id":"A","text":"În zona frontală sunt de elecție variantele cu fluiditate mare ale materialelor aderente fizionomice."},{"id":"B","text":"În zona laterală, primează estetica materialului în detrimentul rezistenței mecanice."},{"id":"C","text":"Materialele cu rășini de tip pastă pot fi folosite în zona frontală dacă sunt asociate cu sisteme adezive cu microumplutură."},{"id":"D","text":"În zona frontală, materialele necesită o rezistență mecanică foarte mare pentru protecția zonei de colet."},{"id":"E","text":"În zona laterală, materialele necesită rezistență mecanică foarte mare, fiind indicate de elecție cimenturile cu ionomeri de sticlă și cimenturile ionomere de sticlă modificate cu rășini."}],"correct":["A","C"],"pages":[83],"source":"set-2"},{"id":"set2--pHyOKT5","fingerprint":"efc5653d97c13f14","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile tehnicii de aplicare în masă a materialelor de restaurare în cavitățile de clasa a V-a?","options":[{"id":"A","text":"Cimenturile cu ionomeri de sticlă aplicate în masă prezintă o fizionomie foarte ridicată."},{"id":"B","text":"Compozitele de tip „bulk” prezintă fizionomie superioară, fiind materialul de elecție pentru zona frontală."},{"id":"C","text":"Cavitățile de dimensiuni mici din zona frontală pot fi obturate cu o singură masă de material care se aplică în straturi de maxim 2 mm."},{"id":"D","text":"În zona frontală, se pot obtura prin această tehnică doar cavități cu extindere mică."},{"id":"E","text":"În zona laterală se pot obtura cavități cu extindere mică, medie și mare, neexistând exigențe fizionomice."}],"correct":["C","D","E"],"pages":[83],"source":"set-2"},{"id":"set2-JpSGGs2B","fingerprint":"4c172943ed435d19","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce roluri și caracteristici prezintă matricele cervicale utilizate în restaurarea cavităților de clasa a V-a?","options":[{"id":"A","text":"Favorizează fotopolimerizarea materialului de restaurare în absența oxigenului."},{"id":"B","text":"Retenționează materialul de restaurare în cazul în care acesta are o consistență fluidă."},{"id":"C","text":"Asigură conformarea morfologică și funcțională a materialului de restaurare de durată."},{"id":"D","text":"Se aplică exclusiv sub primul strat de material în tehnica stratificată."},{"id":"E","text":"Utilizarea matricei este absolut obligatorie pentru toate materialele, inclusiv cele de tip pastă."}],"correct":["A","B","C"],"pages":[84],"source":"set-2"},{"id":"set2-ltNFK6KX","fingerprint":"b97d49cfdfcc5706","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care este scopul utilizării gelului transparent cu glicerină în restaurarea cavităților de clasa a V-a și care sunt condițiile aplicării acestuia?","options":[{"id":"A","text":"Favorizează obținerea unui strat superficial de compozit neinhibat de oxigen."},{"id":"B","text":"Acoperirea cu gel transparent se folosește în situația în care stratul final de compozit nu este acoperit de o matrice."},{"id":"C","text":"Se aplică înainte de fotopolimerizare pentru a menține proprietățile intrinseci optime ale materialului."},{"id":"D","text":"Gelul cu glicerină se aplică după etapa de fotopolimerizare pentru a hidrata suprafața compozitului."},{"id":"E","text":"Asigură inhibarea prin oxigen a compozitului pentru a facilita aderența unui nou strat."}],"correct":["A","B","C"],"pages":[84],"source":"set-2"},{"id":"set2-74gKrPxl","fingerprint":"465cb217710753a4","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la etapa de finisare și lustruire a materialelor compozite moderne?","options":[{"id":"A","text":"Manevrele de finisare și lustruire trebuie efectuate de rutină, fiind obligatorii pentru succesul clinic al oricărei restaurări."},{"id":"B","text":"Finisarea obturațiilor se realizează exclusiv înaintea verificării ocluziei statice și dinamice."},{"id":"C","text":"Amânarea lustruirii cu minimum 24 de ore permite materialului compozit să atingă o rată de conversie maximă."},{"id":"D","text":"Utilizarea instrumentarului rotativ pentru finisare și lustruire produce microfracturi la nivelul suprafeței materialului."},{"id":"E","text":"Finisarea de finețe și lustruirea sunt recomandate a fi realizate în aceeași ședință de tratament pentru a preveni contaminarea salivară."}],"correct":["C","D"],"pages":[84],"source":"set-2"},{"id":"set2-DqHP8HRa","fingerprint":"a774bd96190f5531","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care este compoziția și rolul principal al sigilantului de suprafață („surface sealant”) aplicat peste materialele compozite de durată?","options":[{"id":"A","text":"Este un lac protector a cărui aplicare este obligatorie peste orice tip de material compozit pentru a asigura polimerizarea finală."},{"id":"B","text":"Este un lac pe bază de solvent care se aplică exclusiv sub matricea metalică pentru a preveni lipirea acesteia de peretele vertical."},{"id":"C","text":"Este un produs pe bază de monomer fără umplutură și solvent, care umple microfisurile apărute în urma finisării și lustruirii."},{"id":"D","text":"Este o rășină cu conținut ridicat de umplutură anorganică, menită să crească rezistența la uzură, aplicată o singură dată."},{"id":"E","text":"Este un adeziv amelo-dentinar ce trebuie reîmprospătat la un interval de aproximativ 12 luni pentru menținerea luciului."}],"correct":["C"],"pages":[84],"source":"set-2"},{"id":"set2-FWxcLPuG","fingerprint":"aed3902e68c68dec","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele proceduri sunt incluse în protocoalele de finisare și protecție a suprafeței materialelor de restaurare?","options":[{"id":"A","text":"Finisarea obturațiilor cuplată cu o fotopolimerizare suplimentară a materialului de restaurare."},{"id":"B","text":"Aplicarea obligatorie a unui sigilant de suprafață peste materialele compozite pentru a preveni apariția microfracturilor."},{"id":"C","text":"Menținerea matricei metalice și răsfrângerea ei peste fața proximală a dintelui vecin pentru protecția acestuia în timpul finisării închiderii marginale."},{"id":"D","text":"Aplicarea obligatorie a unui lac protector peste restaurările din ciment ionomer de sticlă (CIS)."},{"id":"E","text":"Reîmprospătarea sigilantului de suprafață pe bază de monomer fără umplutură la intervale regulate de aproximativ 2 ani."}],"correct":["A","C","D"],"pages":[84],"source":"set-2"},{"id":"set2-iEYea9T5","fingerprint":"31d2173d1b5bdb56","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele afirmații referitoare la evaluarea și reparația restaurărilor din compozit este adevărată?","options":[{"id":"A","text":"Rășinile compozite pe bază de metacrilat pot fi aplicate în siguranță peste cele pe bază de silorani, asigurând o închidere etanșă."},{"id":"B","text":"Când tipul materialului inițial este necunoscut, succesul intervenției este favorizat de prelucrarea mecanică a suprafeței pentru crearea de microretenții."},{"id":"C","text":"Defectele mici și medii impun îndepărtarea în totalitate a restaurării și reaplicarea materialului."},{"id":"D","text":"Defectele mari pot fi remediate prin preparații minime, localizate exclusiv la nivelul închiderii marginale."},{"id":"E","text":"Pentru corectarea defectelor, suprafața compozitului este tratată exclusiv cu acid pentru demineralizare, fără a utiliza instrumentar mecanic abraziv."}],"correct":["B"],"pages":[85],"source":"set-2"},{"id":"set2-qspnABtr","fingerprint":"b71716eac9b8cb40","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care sunt caracteristicile tratamentului și ale configurației noilor cavități în abordarea cariilor secundare?","options":[{"id":"A","text":"Noile cavități rezultate sunt frecvent mai mari decât preparațiile anterioare, datorită exerezei suplimentare a structurilor alterate."},{"id":"B","text":"Cavitățile rezultate în urma îndepărtării amalgamului necesită menținerea unor retentivități unghiulare pronunțate pentru noile materiale aderente."},{"id":"C","text":"Interiorul noilor cavități trebuie să prezinte un aspect rotunjit, indiferent dacă materialul de restaurare înlocuit a fost fizionomic sau nefizionomic."},{"id":"D","text":"Timpul chirurgical cuprinde o etapă suplimentară care constă în îndepărtarea mecanică a vechiului material de restaurare."},{"id":"E","text":"Păstrarea dentinei necrotice în profunzime este indicată pentru a limita creșterea în volum a noii preparații."}],"correct":["A","C","D"],"pages":[85],"source":"set-2"},{"id":"set2-R3zr3k4I","fingerprint":"34e89cab60c06d90","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Care dintre următoarele afirmații descriu corect etiopatogenia și caracteristicile tratamentului cavităților de clasa a VI-a?","options":[{"id":"A","text":"Necesitatea retenției suplimentare, obținută de exemplu prin pini parapulpari, este impusă de localizarea în zone supuse unor forțe mecanice directe de mare intensitate."},{"id":"B","text":"Adâncimea acestor cavități este, de regulă, masivă, peretele pulpar aflându-se frecvent în imediata proximitate a camerei pulpare."},{"id":"C","text":"Preparațiile cavităților de clasa a VI-a au frecvent un aspect intern rotunjit, obținut prin utilizarea frezelor sferice la turație redusă."},{"id":"D","text":"Leziunile carioase se dezvoltă frecvent pe zone coronare nerețentive în mod natural, precum vârfurile cuspizilor, devenite retentive consecutiv atriției."},{"id":"E","text":"Uzura mai lentă a dentinei comparativ cu smalțul determină formarea unor suprafețe cu un pronunțat relief convex, favorabil autocurățirii."}],"correct":["A","C","D"],"pages":[85],"source":"set-2"},{"id":"set2-HtJITMYJ","fingerprint":"bdddd9276533b4f0","chapterId":"set-2","subchapterId":"set2-1.07","type":"CS","text":"Care dintre următoarele elemente este specific preparării cavităților de clasa a VI-a și alegerii materialelor de restaurare corespunzătoare?","options":[{"id":"A","text":"Materialele preferate sunt pastele fără proprietăți fizionomice deosebite, prioritară fiind doar rezistența materialului."},{"id":"B","text":"Se impune utilizarea unor materiale de restaurare cu rezistență mecanică scăzută pentru a prelua șocul ocluzal prin deformare elastică."},{"id":"C","text":"Marginile cavităților se nivelează frecvent exclusiv prin utilizarea instrumentarului mecanic la turație redusă."},{"id":"D","text":"Pereții juxtapulpari ai acestor preparații se găsesc de obicei la o distanță sigură de camera pulpară, cavitatea având o adâncime redusă sau medie."},{"id":"E","text":"Bizotarea marginilor este un procedeu evitat în totalitate în zonele laterale, indiferent de forțele ocluzale existente."}],"correct":["D"],"pages":[85],"source":"set-2"},{"id":"set2-N2QA1x7s","fingerprint":"1773399bf2077b90","chapterId":"set-2","subchapterId":"set2-1.07","type":"CM","text":"Ce proceduri se aplică în mod corect pentru remedierea defectelor limitate ale închiderii marginale sau a golurilor apărute la nivelul unei restaurări compozite?","options":[{"id":"A","text":"Extirparea completă a restaurării de durată, deoarece reparațiile localizate compromit sigilarea parodontală."},{"id":"B","text":"Materialul rășinic nou se aplică doar în masă, fiind strict interzisă aplicarea stratificată în cazul reparațiilor marginale."},{"id":"C","text":"Suprafața compozitului restant este obligatoriu prelucrată prin intermediul instrumentarului mecanic abraziv sau prin abraziune cu aer."},{"id":"D","text":"Acidul se aplică strict pentru demineralizarea structurii dure dentare și pentru curățarea suprafețelor preparate."},{"id":"E","text":"Se realizează preparații localizate ce îndepărtează exclusiv materialul de restaurare degradat, protejând integral structura dură adiacentă."}],"correct":["C","D"],"pages":[85],"source":"set-2"}];
